function ClientDocuments({ clientId, documents, onUpload, onDelete }) {
  const [file, setFile] = useState(null);
  const [title, setTitle] = useState("");
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState("");
  const fileInputRef = useRef(null);

  async function handleUpload() {
    if (!file) return;
    setUploading(true);
    setError("");
    const r = await onUpload({ clientId, file, title });
    setUploading(false);
    if (r?.error) { setError(r.error); return; }
    setFile(null);
    setTitle("");
    if (fileInputRef.current) fileInputRef.current.value = "";
  }

  function fmtSize(bytes) {
    if (!bytes) return "";
    if (bytes < 1024 * 1024) return `${Math.round(bytes / 1024)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  }

  return (
    <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: 18, marginTop: 24 }}>
      <div style={{ fontSize: 10.5, fontWeight: 600, color: "#D6D3C7", marginBottom: 12 }}>Documentos (laudos, contratos, fotos)</div>
      <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap", alignItems: "center" }}>
        <input ref={fileInputRef} type="file" onChange={(e) => setFile(e.target.files[0] || null)} style={{ fontSize: 10.5, color: "#D6D3C7" }} />
        <input style={{ ...inputStyle, width: 180 }} placeholder="Nome do documento (opcional)" value={title} onChange={(e) => setTitle(e.target.value)} />
        <PrimaryBtn onClick={handleUpload} disabled={!file || uploading}>
          {uploading ? "Enviando…" : "Enviar"}
        </PrimaryBtn>
      </div>
      {error && <div style={{ fontSize: 10.5, color: "#E38B84", marginBottom: 10 }}>{error}</div>}
      {documents.length === 0 ? (
        <div style={{ color: "#6B7268", fontSize: 10.5 }}>Nenhum documento enviado ainda.</div>
      ) : (
        <div style={{ display: "flex", flexDirection: "column", gap: 8 }}>
          {documents.map((d) => (
            <div key={d.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", background: "#10140F", border: "1px solid #212922", borderRadius: 8, padding: "9px 12px" }}>
              <a href={d.url} target="_blank" rel="noreferrer" style={{ fontSize: 10.5, color: "#D6D3C7", fontWeight: 600, textDecoration: "none" }}>{d.title}</a>
              <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                <span style={{ fontSize: 9.5, color: "#6B7268" }}>{fmtSize(d.sizeBytes)} · {fmtDate(d.uploadedAt?.slice(0, 10))}</span>
                <button onClick={() => { if (confirm(`Remover o documento "${d.title}"?`)) onDelete(d); }} style={iconBtnStyle}><Trash2 size={13} /></button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

const SOIL_NUTRIENTS = [
  { key: "ph", label: "pH", unit: "" },
  { key: "p", label: "Fósforo (P)", unit: "mg/dm³" },
  { key: "p_mel", label: "Fósforo Mehlich (P Mel)", unit: "mg/dm³" },
  { key: "p_res", label: "Fósforo Resina (P Res)", unit: "mg/dm³" },
  { key: "k", label: "Potássio (K)", unit: "mg/dm³" },
  { key: "ca", label: "Cálcio (Ca)", unit: "cmolc/dm³" },
  { key: "mg", label: "Magnésio (Mg)", unit: "cmolc/dm³" },
  { key: "al", label: "Alumínio (Al)", unit: "cmolc/dm³" },
  { key: "ctc", label: "CTC", unit: "cmolc/dm³" },
  { key: "v", label: "Saturação de bases (V%)", unit: "%" },
  { key: "mo", label: "Matéria orgânica", unit: "g/dm³" },
  { key: "s", label: "Enxofre (S)", unit: "mg/dm³" },
  { key: "b", label: "Boro (B)", unit: "mg/dm³" },
  { key: "cu", label: "Cobre (Cu)", unit: "mg/dm³" },
  { key: "fe", label: "Ferro (Fe)", unit: "mg/dm³" },
  { key: "mn", label: "Manganês (Mn)", unit: "mg/dm³" },
  { key: "zn", label: "Zinco (Zn)", unit: "mg/dm³" },
];

// Duas camadas de coleta (0-20cm é a padrão/principal, já usada em tudo do
// jeito que sempre foi; 20-40cm é opcional — só existe quando a planilha
// importada traz uma segunda coluna por nutriente pra essa profundidade).
// A camada funda usa a mesma chave do nutriente com o sufixo "_20_40".
const SOIL_DEPTHS = [
  { key: "0-20", label: "0-20cm", suffix: "" },
  { key: "20-40", label: "20-40cm", suffix: "_20_40" },
];
function soilDepthKey(nutrientKey, depth) {
  const d = SOIL_DEPTHS.find((x) => x.key === depth) || SOIL_DEPTHS[0];
  return `${nutrientKey}${d.suffix}`;
}

const SOIL_COLUMN_ALIASES = {
  label: ["ponto", "amostra", "id", "point", "label", "identificacao", "numero", "número", "no"],
  ph: ["ph"],
  p: ["p", "fosforo", "fósforo"],
  p_mel: ["pmel", "pmehlich", "pmelich", "fosforomehlich", "fósforomehlich", "fosforomelich"],
  p_res: ["pres", "presina", "fosfororesina", "fósfororesina"],
  k: ["k", "potassio", "potássio"],
  ca: ["ca", "calcio", "cálcio"],
  mg: ["mg", "magnesio", "magnésio"],
  al: ["al", "aluminio", "alumínio"],
  ctc: ["ctc"],
  v: ["v", "v%", "saturacaodebases", "saturaçãodebases", "satbases"],
  mo: ["mo", "materiaorganica", "matériaorgânica"],
  s: ["s", "enxofre"],
  b: ["b", "boro"],
  cu: ["cu", "cobre"],
  fe: ["fe", "ferro"],
  mn: ["mn", "manganes", "manganês"],
  zn: ["zn", "zinco"],
};

function normalizeSpreadsheetHeader(h) {
  return String(h || "")
    .normalize("NFD").replace(/[̀-ͯ]/g, "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9%]/g, "");
}

// Marcas de profundidade dentro do cabeçalho já normalizado (sem espaços/
// hífen/parênteses) — cobrem "20-40", "20 a 40", "20/40" (viram "2040" ou
// "20a40") e também "0-20", "0 a 20" (viram "020" ou "0a20"), pro caso da
// planilha rotular a camada padrão explicitamente também, não só a funda.
const SOIL_DEPTH1_MARKER = /0a?20/;
const SOIL_DEPTH2_MARKER = /20a?40/;

function mapSoilColumns(headerRow) {
  const normalized = headerRow.map((h) => normalizeSpreadsheetHeader(h));
  const mapping = {};
  normalized.forEach((h, idx) => {
    if (!h) return;
    const isDepth2 = SOIL_DEPTH2_MARKER.test(h);
    const stripped = isDepth2 ? h.replace(SOIL_DEPTH2_MARKER, "") : h.replace(SOIL_DEPTH1_MARKER, "");
    for (const [key, aliases] of Object.entries(SOIL_COLUMN_ALIASES)) {
      if (!aliases.includes(stripped)) continue;
      const finalKey = isDepth2 && key !== "label" ? soilDepthKey(key, "20-40") : key;
      if (mapping[finalKey] === undefined) mapping[finalKey] = idx;
      break;
    }
  });
  // Quase todo laudo de laboratório traz o identificador do ponto na
  // primeira coluna, mesmo quando o cabeçalho usa um nome que não está na
  // nossa lista de sinônimos — usa a coluna 0 como último recurso em vez de
  // simplesmente falhar a importação inteira por causa do nome de uma coluna.
  if (mapping.label === undefined && headerRow.length > 0 && normalized[0] !== "") {
    mapping.label = 0;
  }
  return mapping;
}

async function parseSoilSpreadsheet(file) {
  const isCsv = /\.csv$/i.test(file.name);
  const workbook = isCsv
    ? XLSX.read(await file.text(), { type: "string" })
    : XLSX.read(await file.arrayBuffer(), { type: "array" });
  const sheet = workbook.Sheets[workbook.SheetNames[0]];
  const rows = XLSX.utils.sheet_to_json(sheet, { header: 1, raw: true, defval: "" });
  if (rows.length < 2) return { rows: [], mapping: {} };
  const mapping = mapSoilColumns(rows[0]);
  const dataRows = rows.slice(1).filter((r) => r.some((c) => c !== "" && c !== null && c !== undefined));
  const parsed = dataRows.map((r) => {
    const entry = {};
    Object.entries(mapping).forEach(([key, idx]) => {
      const raw = r[idx];
      entry[key] = key === "label" ? String(raw ?? "").trim() : (raw === "" || raw === undefined || raw === null ? null : Number(raw));
    });
    return entry;
  });
  return { rows: parsed, mapping };
}

function pointInPolygon(lat, lng, polygon) {
  let inside = false;
  for (let i = 0, j = polygon.length - 1; i < polygon.length; j = i++) {
    const [yi, xi] = polygon[i];
    const [yj, xj] = polygon[j];
    const intersect = (yi > lat) !== (yj > lat) && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi;
    if (intersect) inside = !inside;
  }
  return inside;
}

function idwInterpolate(lat, lng, points, valueKey, power = 2) {
  let weightedSum = 0, weightSum = 0;
  for (const p of points) {
    const val = Number(p[valueKey]);
    if (p[valueKey] === undefined || p[valueKey] === "" || Number.isNaN(val)) continue;
    const d = Math.hypot(p.lat - lat, p.lng - lng);
    if (d < 1e-9) return val;
    const w = 1 / Math.pow(d, power);
    weightedSum += w * val;
    weightSum += w;
  }
  return weightSum > 0 ? weightedSum / weightSum : null;
}

function heatColor(t) {
  const stops = [[0, [214, 69, 65]], [0.5, [227, 180, 85]], [1, [123, 193, 66]]];
  for (let i = 0; i < stops.length - 1; i++) {
    const [t0, c0] = stops[i], [t1, c1] = stops[i + 1];
    if (t >= t0 && t <= t1) {
      const f = t1 > t0 ? (t - t0) / (t1 - t0) : 0;
      return [
        Math.round(c0[0] + f * (c1[0] - c0[0])),
        Math.round(c0[1] + f * (c1[1] - c0[1])),
        Math.round(c0[2] + f * (c1[2] - c0[2])),
      ];
    }
  }
  return stops[stops.length - 1][1];
}

const HEAT_NUM_CLASSES = 5;

// Mapa de calor "em blocos" (classificado em faixas de igual amplitude), no
// estilo de mapa de prescrição usado no mercado (Geodata etc.) — cores sólidas
// por faixa em vez de gradiente contínuo, com área/porcentagem por faixa pra
// dar dimensão real de quanto do talhão cai em cada nível.
function buildHeatOverlay(polygon, points, valueKey, resolution = 70, numClasses = HEAT_NUM_CLASSES) {
  if (!polygon || polygon.length < 3) return null;
  const values = points
    .map((p) => Number(p[valueKey]))
    .filter((v) => isValidNumber(v));
  if (values.length === 0) return null;
  const minV = Math.min(...values), maxV = Math.max(...values);
  const range = maxV > minV ? maxV - minV : 1;
  const breaks = [];
  for (let i = 0; i <= numClasses; i++) breaks.push(minV + (range * i) / numClasses);
  function classify(val) {
    if (maxV <= minV) return 0;
    const idx = Math.floor(((val - minV) / range) * numClasses);
    return Math.max(0, Math.min(numClasses - 1, idx));
  }
  const classColors = [];
  for (let i = 0; i < numClasses; i++) {
    const t = numClasses > 1 ? i / (numClasses - 1) : 0.5;
    classColors.push(heatColor(t));
  }

  const lats = polygon.map((p) => p[0]);
  const lngs = polygon.map((p) => p[1]);
  const minLat = Math.min(...lats), maxLat = Math.max(...lats);
  const minLng = Math.min(...lngs), maxLng = Math.max(...lngs);
  const w = resolution, h = resolution;
  const canvas = document.createElement("canvas");
  canvas.width = w;
  canvas.height = h;
  const ctx = canvas.getContext("2d");
  const imgData = ctx.createImageData(w, h);
  const classCounts = new Array(numClasses).fill(0);
  let totalCount = 0;
  let sumVal = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const lat = maxLat - (y / (h - 1)) * (maxLat - minLat);
      const lng = minLng + (x / (w - 1)) * (maxLng - minLng);
      const idx = (y * w + x) * 4;
      if (!pointInPolygon(lat, lng, polygon)) continue;
      const val = idwInterpolate(lat, lng, points, valueKey);
      if (val === null) continue;
      const cls = classify(val);
      const [r, g, b] = classColors[cls];
      imgData.data[idx] = r;
      imgData.data[idx + 1] = g;
      imgData.data[idx + 2] = b;
      imgData.data[idx + 3] = 210;
      classCounts[cls]++;
      totalCount++;
      sumVal += val;
    }
  }
  ctx.putImageData(imgData, 0, 0);
  return {
    dataUrl: canvas.toDataURL(), bounds: [[minLat, minLng], [maxLat, maxLng]], minV, maxV,
    avgV: totalCount > 0 ? sumVal / totalCount : (minV + maxV) / 2,
    breaks, classColors, classCounts, totalCount, numClasses,
  };
}

function isValidNumber(v) {
  return typeof v === "number" && !Number.isNaN(v);
}

// Método da saturação por bases (NC em t/ha, considerando calcário com PRNT 100%):
// NC = CTC x (V2 desejado - V1 atual) / 100. Não recomenda calcário se a
// saturação atual já está no nível desejado ou acima.
function limeNeedTonPerHa(point, desiredV) {
  const ctc = Number(point.ctc);
  const v = Number(point.v);
  if (Number.isNaN(ctc) || Number.isNaN(v) || Number.isNaN(desiredV)) return null;
  return Math.max(0, (ctc * (desiredV - v)) / 100);
}

// Adubação NPK pelo método de reposição/exportação: dose (kg/ha) = quanto a
// cultura exporta do nutriente por tonelada de grão x produtividade esperada.
// Os coeficientes de exportação por cultura são valores de referência comuns
// na agronomia brasileira — ficam editáveis na tela porque variam por região,
// cultivar e histórico de adubação, e quem deve calibrá-los é o agrônomo.
const NPK_CROPS = [
  { key: "soja", label: "Soja", n: 0, p2o5: 14, k2o: 20 },
  { key: "milho", label: "Milho", n: 20, p2o5: 8, k2o: 18 },
  { key: "algodao", label: "Algodão", n: 40, p2o5: 16, k2o: 25 },
  { key: "trigo", label: "Trigo", n: 25, p2o5: 11, k2o: 16 },
  { key: "outra", label: "Outra cultura", n: 0, p2o5: 0, k2o: 0 },
];

function npkDoseKgPerHa(yieldGoal, exportPerTon) {
  const y = Number(yieldGoal), e = Number(exportPerTon);
  if (Number.isNaN(y) || Number.isNaN(e)) return null;
  return Math.max(0, y * e);
}

function avgNutrient(points, key) {
  const values = points
    .filter((p) => p[key] !== undefined && p[key] !== "" && !Number.isNaN(Number(p[key])))
    .map((p) => Number(p[key]));
  return values.length ? values.reduce((s, v) => s + v, 0) / values.length : null;
}

const WHITE_TILE_URL = "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAACCAIAAAD91JpzAAAADklEQVR42mP4DwYMEAoAU7oL9YXEbhEAAAAASUVORK5CYII=";

function MapClickCapture({ onClick }) {
  useMapEvents({ click(e) { onClick(e.latlng.lat, e.latlng.lng); } });
  return null;
}

function toGeoJsonRing(latLngPairs) {
  const ring = latLngPairs.map(([lat, lng]) => [lng, lat]);
  const first = ring[0], last = ring[ring.length - 1];
  if (!first || !last || first[0] !== last[0] || first[1] !== last[1]) ring.push(first);
  return ring;
}

// Gera uma zona de manejo (polígono de Voronoi recortado pelo limite do
// talhão) em volta de cada ponto de coleta, com o valor do atributo pra
// aplicação a taxa variável — é assim que a maioria dos monitores de
// plantadeira/distribuidor (John Deere GS3, Stara etc.) espera um mapa de
// prescrição em shapefile: polígono + coluna numérica de taxa, não pontos soltos.
function buildVoronoiPrescriptionGeoJSON(fieldPolygonLatLng, points, valueFieldName, getValue) {
  const fieldRing = toGeoJsonRing(fieldPolygonLatLng);
  const fieldMultiPoly = [[fieldRing]];

  const lats = fieldPolygonLatLng.map((p) => p[0]);
  const lngs = fieldPolygonLatLng.map((p) => p[1]);
  const pad = 0.01;
  const bounds = [Math.min(...lngs) - pad, Math.min(...lats) - pad, Math.max(...lngs) + pad, Math.max(...lats) + pad];

  const validPoints = points.filter((p) => {
    const v = getValue(p);
    return v !== null && v !== undefined && !Number.isNaN(v);
  });
  if (validPoints.length < 2) return { type: "FeatureCollection", features: [] };

  const delaunay = Delaunay.from(validPoints, (p) => p.lng, (p) => p.lat);
  const voronoi = delaunay.voronoi(bounds);

  const features = [];
  validPoints.forEach((p, i) => {
    const cell = voronoi.cellPolygon(i);
    if (!cell) return;
    let clipped;
    try {
      clipped = intersection([[cell]], fieldMultiPoly);
    } catch (e) {
      clipped = null;
    }
    if (!clipped || clipped.length === 0) return;
    clipped.forEach((polyRings) => {
      features.push({
        type: "Feature",
        properties: { [valueFieldName]: Number(getValue(p).toFixed(2)), PONTO: p.label },
        geometry: { type: "Polygon", coordinates: polyRings },
      });
    });
  });

  return { type: "FeatureCollection", features };
}

async function downloadShapefileZip(geojson, fileNamePrefix, field) {
  if (geojson.features.length === 0) throw new Error("Nada pra exportar nesse mapa.");
  const blob = await shpwrite.zip(geojson, { outputType: "blob", compression: "DEFLATE", types: { polygon: "zonas" } });
  const safeName = `${fileNamePrefix}_${field.name}`.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-zA-Z0-9]/g, "_");
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${safeName}.zip`;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

async function downloadPrescriptionShapefile(field, points, valueFieldName, getValue, fileNamePrefix) {
  const polygon = field.fieldMap?.mode === "kml" ? field.fieldMap.points : [];
  if (polygon.length < 3) throw new Error("Esse talhão não tem área definida por KML.");
  const geojson = buildVoronoiPrescriptionGeoJSON(polygon, points, valueFieldName, getValue);
  await downloadShapefileZip(geojson, fileNamePrefix, field);
}

// NDVI: converte a imagem em tons de cinza (0=NDVI -1, 255=NDVI +1) devolvida
// pela função sentinel-ndvi numa grade de valores de NDVI, decodificando via
// canvas. Pixel com alfa baixo = sem dado válido (nuvem, fora da cena).
function decodeNdviGrid(dataUrl, width, height) {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onerror = () => reject(new Error("Não consegui decodificar a imagem NDVI recebida."));
    img.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext("2d");
      ctx.drawImage(img, 0, 0, width, height);
      const imgData = ctx.getImageData(0, 0, width, height);
      const values = new Array(width * height);
      for (let i = 0; i < width * height; i++) {
        const idx = i * 4;
        if (imgData.data[idx + 3] < 128) { values[i] = null; continue; }
        values[i] = imgData.data[idx] / 127.5 - 1;
      }
      resolve({ width, height, values });
    };
    img.src = dataUrl;
  });
}

function ndviColor(t) {
  const stops = [[0, [166, 97, 26]], [0.5, [223, 194, 125]], [1, [26, 152, 80]]];
  for (let i = 0; i < stops.length - 1; i++) {
    const [t0, c0] = stops[i], [t1, c1] = stops[i + 1];
    if (t >= t0 && t <= t1) {
      const f = t1 > t0 ? (t - t0) / (t1 - t0) : 0;
      return [
        Math.round(c0[0] + f * (c1[0] - c0[0])),
        Math.round(c0[1] + f * (c1[1] - c0[1])),
        Math.round(c0[2] + f * (c1[2] - c0[2])),
      ];
    }
  }
  return stops[stops.length - 1][1];
}

function buildNdviOverlayImage(grid, bounds) {
  const { width, height, values } = grid;
  // Math.min/max(...array) estoura a pilha de chamadas em imagens grandes
  // (até 512x512 = 260 mil+ pixels) — precisa somar min/max num laço comum.
  let minV = Infinity, maxV = -Infinity, hasValid = false;
  for (let i = 0; i < values.length; i++) {
    const v = values[i];
    if (v === null) continue;
    hasValid = true;
    if (v < minV) minV = v;
    if (v > maxV) maxV = v;
  }
  if (!hasValid) return null;
  const canvas = document.createElement("canvas");
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  const imgData = ctx.createImageData(width, height);
  for (let i = 0; i < values.length; i++) {
    const idx = i * 4;
    const v = values[i];
    if (v === null) { imgData.data[idx + 3] = 0; continue; }
    const t = maxV > minV ? (v - minV) / (maxV - minV) : 0.5;
    const [r, g, b] = ndviColor(t);
    imgData.data[idx] = r; imgData.data[idx + 1] = g; imgData.data[idx + 2] = b; imgData.data[idx + 3] = 210;
  }
  ctx.putImageData(imgData, 0, 0);
  return { dataUrl: canvas.toDataURL(), bounds, minV, maxV };
}

// Simplificação de Douglas-Peucker: reduz o número de vértices de um
// contorno mantendo a forma geral — usada pra suavizar o efeito "escada de
// quadradinhos" que sobra de unir células de uma grade.
function perpendicularDistance(x0, y0, x1, y1, x2, y2) {
  const dx = x2 - x1, dy = y2 - y1;
  const len = Math.hypot(dx, dy);
  if (len === 0) return Math.hypot(x0 - x1, y0 - y1);
  return Math.abs(dy * x0 - dx * y0 + x2 * y1 - y2 * x1) / len;
}
function douglasPeucker(points, epsilon) {
  if (points.length < 3) return points;
  let maxDist = 0, index = 0;
  const [x1, y1] = points[0], [x2, y2] = points[points.length - 1];
  for (let i = 1; i < points.length - 1; i++) {
    const [x0, y0] = points[i];
    const dist = perpendicularDistance(x0, y0, x1, y1, x2, y2);
    if (dist > maxDist) { maxDist = dist; index = i; }
  }
  if (maxDist > epsilon) {
    const left = douglasPeucker(points.slice(0, index + 1), epsilon);
    const right = douglasPeucker(points.slice(index), epsilon);
    return left.slice(0, -1).concat(right);
  }
  return [points[0], points[points.length - 1]];
}
function simplifyPolygonRings(polyRings, epsilon) {
  return polyRings.map((ring) => {
    const simplified = douglasPeucker(ring, epsilon);
    return simplified.length >= 4 ? simplified : ring;
  });
}

// Classifica o talhão em zonas de manejo a partir do NDVI: amostra uma grade
// fina de células sobre a imagem, agrupa cada célula numa classe por
// quantil, recorta pelo limite real do talhão e funde (union) as células
// vizinhas da mesma classe num polígono só por zona — depois suaviza o
// contorno resultante (menos "escada de quadradinhos", menos vértices).
function classifyNdviZones(fieldPolygonLatLng, bounds, grid, numClasses) {
  const [[minLat, minLng], [maxLat, maxLng]] = bounds;
  const { width, height, values } = grid;
  const cellsPerSide = 24;
  const cellW = (maxLng - minLng) / cellsPerSide;
  const cellH = (maxLat - minLat) / cellsPerSide;
  const fieldMultiPoly = [[toGeoJsonRing(fieldPolygonLatLng)]];

  function sampleAt(lat, lng) {
    const px = Math.floor(((lng - minLng) / (maxLng - minLng)) * width);
    const py = Math.floor(((maxLat - lat) / (maxLat - minLat)) * height);
    if (px < 0 || px >= width || py < 0 || py >= height) return null;
    return values[py * width + px];
  }

  const cellData = [];
  for (let r = 0; r < cellsPerSide; r++) {
    for (let c = 0; c < cellsPerSide; c++) {
      const cellMinLng = minLng + c * cellW, cellMaxLng = cellMinLng + cellW;
      const cellMinLat = minLat + r * cellH, cellMaxLat = cellMinLat + cellH;
      const val = sampleAt((cellMinLat + cellMaxLat) / 2, (cellMinLng + cellMaxLng) / 2);
      if (val === null) continue;
      cellData.push({ cellMinLng, cellMaxLng, cellMinLat, cellMaxLat, val });
    }
  }
  if (cellData.length === 0) return { zones: [], breaks: [] };

  const sortedVals = cellData.map((c) => c.val).sort((a, b) => a - b);
  const breaks = [];
  for (let i = 1; i < numClasses; i++) {
    const idx = Math.min(Math.floor((i / numClasses) * sortedVals.length), sortedVals.length - 1);
    breaks.push(sortedVals[idx]);
  }
  const classify = (val) => {
    for (let i = 0; i < breaks.length; i++) { if (val <= breaks[i]) return i; }
    return breaks.length;
  };

  const byClass = {};
  cellData.forEach((cell) => {
    const cls = classify(cell.val);
    const ring = [
      [cell.cellMinLng, cell.cellMinLat], [cell.cellMaxLng, cell.cellMinLat],
      [cell.cellMaxLng, cell.cellMaxLat], [cell.cellMinLng, cell.cellMaxLat], [cell.cellMinLng, cell.cellMinLat],
    ];
    let clipped;
    try { clipped = intersection([[ring]], fieldMultiPoly); } catch (e) { clipped = null; }
    if (!clipped || clipped.length === 0) return;
    if (!byClass[cls]) byClass[cls] = { polys: [], values: [] };
    clipped.forEach((polyRings) => byClass[cls].polys.push(polyRings));
    byClass[cls].values.push(cell.val);
  });

  const simplifyEpsilon = Math.min(cellW, cellH) * 0.6;
  const zones = Object.entries(byClass).map(([clsStr, { polys, values: vals }]) => {
    let unioned = polys;
    try {
      unioned = polys.reduce((acc, poly) => (acc ? union(acc, [poly]) : [poly]), null) || polys;
    } catch (e) { /* mantém os polígonos não fundidos se a união falhar */ }
    unioned = unioned.map((polyRings) => simplifyPolygonRings(polyRings, simplifyEpsilon));
    const areaHa = unioned.reduce((sum, polyRings) => {
      const outerRing = polyRings[0].map(([lng, lat]) => ({ lat, lng }));
      return sum + geodesicAreaHa(outerRing);
    }, 0);
    return {
      classIndex: Number(clsStr),
      ndviMin: Math.min(...vals),
      ndviMax: Math.max(...vals),
      ndviAvg: vals.reduce((s, v) => s + v, 0) / vals.length,
      areaHa,
      polygons: unioned,
    };
  }).sort((a, b) => a.classIndex - b.classIndex);

  return { zones, breaks };
}

function generatePointsForZone(zone, targetCount) {
  if (targetCount <= 0 || zone.areaHa <= 0) return [];
  const hectaresPerPoint = zone.areaHa / targetCount;
  let points = [];
  zone.polygons.forEach((polyRings) => {
    const outerRing = polyRings[0].map(([lng, lat]) => [lat, lng]);
    points = points.concat(generateSamplingGrid(outerRing, hectaresPerPoint));
  });
  return points;
}

// Baixa uma foto (URL pública do Storage) e devolve como data URL + as
// dimensões reais, pra dar pra encaixar no PDF sem distorcer a proporção.
async function loadImageInfo(url) {
  const res = await fetch(url);
  if (!res.ok) throw new Error("Falha ao baixar a foto.");
  const blob = await res.blob();
  const dataUrl = await new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error("Falha ao ler a foto."));
    reader.readAsDataURL(blob);
  });
  const { width, height } = await new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve({ width: img.naturalWidth || 1, height: img.naturalHeight || 1 });
    img.onerror = () => reject(new Error("Falha ao decodificar a foto."));
    img.src = dataUrl;
  });
  return { dataUrl, width, height };
}

// Relatório de visita(s) técnica(s) pra encaminhar ao produtor — narra o que
// foi observado em campo (estágio, pragas/doenças, recomendações e fotos).
// Aceita uma visita só ou várias (ex: várias áreas visitadas no mesmo dia).
// Miniatura vetorial do contorno do talhão, fundo branco — só uma referência visual
// de formato/posição pro relatório, desenhada direto no PDF (não depende de mapa/rede).
function drawFieldThumbnailPdf(doc, polygonLatLng, x, y, size) {
  doc.setDrawColor(...BOLETIM_RULE);
  doc.setFillColor(255, 255, 255);
  doc.rect(x, y, size, size, "FD");
  if (!polygonLatLng || polygonLatLng.length < 3) return;
  const lats = polygonLatLng.map((p) => p[0]);
  const lngs = polygonLatLng.map((p) => p[1]);
  const minLat = Math.min(...lats), maxLat = Math.max(...lats);
  const minLng = Math.min(...lngs), maxLng = Math.max(...lngs);
  const meanLat = (minLat + maxLat) / 2;
  const corte = Math.cos((meanLat * Math.PI) / 180) || 1;
  const latRange = Math.max(maxLat - minLat, 1e-9);
  const lngRangeCorrigido = Math.max((maxLng - minLng) * corte, 1e-9);
  const pad = size * 0.12;
  const usable = size - pad * 2;
  const scale = Math.min(usable / lngRangeCorrigido, usable / latRange);
  const wUsed = lngRangeCorrigido * scale, hUsed = latRange * scale;
  const offsetX = x + (size - wUsed) / 2, offsetY = y + (size - hUsed) / 2;
  const pts = polygonLatLng.map(([lat, lng]) => [
    offsetX + (lng - minLng) * corte * scale,
    offsetY + hUsed - (lat - minLat) * scale,
  ]);
  const deltas = pts.slice(1).map((p, i) => [p[0] - pts[i][0], p[1] - pts[i][1]]);
  doc.setFillColor(196, 224, 165);
  doc.lines(deltas, pts[0][0], pts[0][1], [1, 1], "F", true);
}

// Paleta do "Boletim Agronômico" — verde institucional + dourado de destaque,
// papel levemente amarelado (não branco puro), no espírito de um boletim/circular
// técnica impressa.
const BOLETIM_GREEN = [27, 58, 30];
const BOLETIM_GOLD = [173, 138, 46];
const BOLETIM_PAPER = [247, 245, 236];
const BOLETIM_INK = [28, 31, 26];
const BOLETIM_INK_SOFT = [91, 97, 86];
const BOLETIM_RULE = [214, 207, 184];
const BOLETIM_STRIPE = [239, 234, 218];

// Uma célula do "quadro de dados" do boletim: rótulo em caixa alta sobre fundo
// listrado, ou o valor correspondente ao lado, ambos com borda fina.
function drawBoletimCell(doc, x, y, w, h, isLabel, text) {
  doc.setDrawColor(...BOLETIM_RULE);
  if (isLabel) { doc.setFillColor(...BOLETIM_STRIPE); doc.rect(x, y, w, h, "FD"); }
  else { doc.rect(x, y, w, h, "D"); }
  if (isLabel) {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(6.4);
    doc.setTextColor(...BOLETIM_INK_SOFT);
    doc.text(text.toUpperCase(), x + 2.5, y + h / 2 + 1.1);
  } else {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.setTextColor(...BOLETIM_INK);
    doc.text(String(text), x + 3, y + h / 2 + 1.3);
  }
}
// Relatório de visita(s) no estilo "Boletim Agronômico" — masthead formal, quadro
// de dados listrado e faixa verde por talhão, no espírito de um boletim técnico
// impresso (escolhido entre 4 direções apresentadas ao cliente).
async function downloadVisitReportPdf(visits) {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();
  const marginX = 14;
  const maxY = 274;
  let y = 18;

  function paintPageBackground() {
    doc.setFillColor(...BOLETIM_PAPER);
    doc.rect(0, 0, pageWidth, pageHeight, "F");
  }
  function ensureSpace(needed) {
    if (y + needed > maxY) { doc.addPage(); paintPageBackground(); y = 20; }
  }

  paintPageBackground();

  const multiple = visits.length > 1;
  const sorted = [...visits].sort((a, b) => a.date.localeCompare(b.date) || a.fieldName.localeCompare(b.fieldName));
  const clientNames = [...new Set(sorted.map((v) => v.clientName))];
  // CPF/CNPJ de cada cliente envolvido no relatório, um por nome (sem repetir), já rotulado
  // conforme o tamanho do documento — pra imprimir junto do nome logo abaixo do cabeçalho.
  const clientDocs = [];
  const seenClientNames = new Set();
  for (const v of sorted) {
    if (v.clientCpfCnpj && !seenClientNames.has(v.clientName)) {
      seenClientNames.add(v.clientName);
      clientDocs.push({ name: v.clientName, doc: v.clientCpfCnpj });
    }
  }
  const dates = [...new Set(sorted.map((v) => v.date))].sort();
  const dateLabel = dates.length === 1 ? fmtDate(dates[0]) : `${fmtDate(dates[0])} a ${fmtDate(dates[dates.length - 1])}`;
  const contentWidth = pageWidth - marginX * 2;

  // --- Masthead ---
  // Logo original é 420x136px (~3.09:1) — mantém a proporção pra não espichar.
  doc.addImage(LOGO_SRC_GREEN, "PNG", marginX, y, 22, 22 / (420 / 136));
  doc.setFont("times", "bold");
  doc.setFontSize(15);
  doc.setTextColor(...BOLETIM_GREEN);
  doc.text("Semear", marginX + 27, y + 6);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(7);
  doc.setTextColor(...BOLETIM_INK_SOFT);
  doc.text("C O N S U L T O R I A   A G R O P E C U Á R I A", marginX + 27, y + 11);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(7.5);
  doc.setTextColor(...BOLETIM_GOLD);
  doc.text(`RELATÓRIO DE VISITA${multiple ? "S" : ""} TÉCNICA${multiple ? "S" : ""}`, pageWidth - marginX, y + 6, { align: "right" });
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8);
  doc.setTextColor(...BOLETIM_INK_SOFT);
  doc.text(`Data d${dates.length === 1 ? "a visita" : "as visitas"}: ${dateLabel}`, pageWidth - marginX, y + 11, { align: "right" });

  y += 16;
  doc.setDrawColor(...BOLETIM_GREEN);
  doc.setLineWidth(0.9);
  doc.line(marginX, y, pageWidth - marginX, y);
  doc.setLineWidth(0.2);
  y += 9;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(11);
  doc.setTextColor(...BOLETIM_INK);
  doc.text(`Cliente: ${clientNames.join(", ")}`, marginX, y);
  y += 6;

  if (clientDocs.length > 0) {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8.5);
    doc.setTextColor(...BOLETIM_INK_SOFT);
    const docLine = clientDocs.length === 1
      ? `${tipoCpfCnpj(clientDocs[0].doc)}: ${clientDocs[0].doc}`
      : clientDocs.map((c) => `${c.name} — ${tipoCpfCnpj(c.doc)}: ${c.doc}`).join("  ·  ");
    doc.text(docLine, marginX, y);
    y += 6;
  }
  y += 2;

  const intro = `Prezado(a) ${clientNames[0] || "produtor(a)"}, segue um resumo d${multiple ? "as visitas técnicas realizadas" : "a visita técnica realizada"} em sua${multiple ? "s área(s)" : " área"}, com as principais observações de campo e recomendações da nossa equipe.`;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(9.5);
  doc.setTextColor(...BOLETIM_INK);
  const introLines = doc.splitTextToSize(intro, contentWidth);
  doc.text(introLines, marginX, y);
  y += introLines.length * 4.3 + 8;

  // --- Uma seção por talhão visitado ---
  for (const v of sorted) {
    ensureSpace(16);
    doc.setFillColor(...BOLETIM_GREEN);
    doc.rect(marginX, y, contentWidth, 8, "F");
    doc.setTextColor(...BOLETIM_PAPER);
    doc.setFont("times", "bold");
    doc.setFontSize(10.5);
    doc.text(`${v.propertyName} · ${v.fieldName}${v.culture ? " · " + v.culture : ""}`, marginX + 3, y + 5.6);
    y += 12;

    // Quadro de dados: Data + Técnico numa linha, Estágio fenológico na seguinte (se houver).
    const rowH = 7;
    ensureSpace(v.stage ? rowH * 2 + 4 : rowH + 4);
    let cx = marginX;
    const w1 = 40, w2 = 62, w3 = 30, w4 = contentWidth - w1 - w2 - w3;
    drawBoletimCell(doc, cx, y, w1, rowH, true, "Data da visita"); cx += w1;
    drawBoletimCell(doc, cx, y, w2, rowH, false, fmtDate(v.date)); cx += w2;
    drawBoletimCell(doc, cx, y, w3, rowH, true, "Técnico"); cx += w3;
    drawBoletimCell(doc, cx, y, w4, rowH, false, v.technician || "—");
    y += rowH;
    if (v.stage) {
      cx = marginX;
      const l1 = 48, l2 = contentWidth - l1;
      drawBoletimCell(doc, cx, y, l1, rowH, true, "Estágio fenológico"); cx += l1;
      drawBoletimCell(doc, cx, y, l2, rowH, false, v.stage);
      y += rowH;
    }
    y += 7;

    // Corpo em duas colunas: texto à esquerda, miniatura do talhão à direita.
    const hasThumb = v.fieldMap?.mode === "kml" && v.fieldMap.points?.length >= 3;
    const thumbSize = 30;
    const textWidth = hasThumb ? contentWidth - thumbSize - 8 : contentWidth;
    // blockTop precisa ser capturado DEPOIS do ensureSpace do bloco da miniatura —
    // se a quebra de página acontecer bem aqui, blockTop tem que refletir o y já
    // corrigido (início da página nova), senão o cálculo de altura da coluna mais
    // embaixo usa uma posição da página anterior e "empurra" o texto pra bem mais
    // longe do que devia, deixando um vão em branco enorme na página.
    if (hasThumb) ensureSpace(thumbSize + 6);
    const blockTop = y;
    if (hasThumb) {
      drawFieldThumbnailPdf(doc, v.fieldMap.points, marginX + textWidth + 8, y, thumbSize);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(6.4);
      doc.setTextColor(...BOLETIM_INK_SOFT);
      doc.text("Referência de talhão", marginX + textWidth + 8 + thumbSize / 2, y + thumbSize + 4, { align: "center" });
    }

    function bodyBlock(label, text) {
      if (!text) return;
      ensureSpace(10);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(7);
      doc.setTextColor(...BOLETIM_GOLD);
      doc.text(label.toUpperCase(), marginX, y);
      y += 4.6;
      doc.setFont("helvetica", "normal");
      doc.setFontSize(9);
      doc.setTextColor(...BOLETIM_INK);
      const lines = doc.splitTextToSize(text, textWidth);
      ensureSpace(lines.length * 4.4);
      doc.text(lines, marginX, y);
      y += lines.length * 4.4 + 5;
    }
    bodyBlock("Pragas / doenças observadas", v.pests);
    bodyBlock("Recomendações", v.recommendations);
    if (hasThumb) y = Math.max(y, blockTop + thumbSize + 8);

    if (v.photos && v.photos.length > 0) {
      const photoW = 85, maxPhotoH = 60;
      for (const p of v.photos) {
        try {
          const info = await loadImageInfo(p.url);
          const ratio = info.width / info.height;
          let w = photoW, h = w / ratio;
          if (h > maxPhotoH) { h = maxPhotoH; w = h * ratio; }
          ensureSpace(h + 6);
          doc.setDrawColor(...BOLETIM_RULE);
          doc.rect(marginX - 1, y - 1, w + 2, h + 2, "D");
          doc.addImage(info.dataUrl, "JPEG", marginX, y, w, h);
          y += h + 5;
        } catch (e) { /* pula foto que não carregou, não trava o relatório inteiro */ }
      }
    }
    y += 5;
  }

  const pageCount = doc.internal.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    doc.setDrawColor(...BOLETIM_RULE);
    doc.setLineWidth(0.2);
    doc.line(marginX, pageHeight - 15, pageWidth - marginX, pageHeight - 15);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.5);
    doc.setTextColor(...BOLETIM_INK_SOFT);
    doc.text(`Gerado em ${fmtDateTime(new Date().toISOString())} · Semear Consultoria Agropecuária`, marginX, pageHeight - 10);
    doc.text(`Pág. ${i}/${pageCount}`, pageWidth - marginX, pageHeight - 10, { align: "right" });
  }

  const safeName = `${clientNames[0] || "visita"}`.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-zA-Z0-9]/g, "_");
  doc.save(`relatorio-visita-${safeName}-${dates[dates.length - 1]}.pdf`);
}

// Desenha o contorno do talhão preenchido dentro de uma caixa (x,y,maxW,maxH),
// preservando a proporção real (corrige a compressão de longitude pela
// latitude) — devolve a função de projeção lat/lng -> ponto do PDF, pra dar
// pra plotar outras coisas (pontos, zonas) na mesma escala/posição.
function drawFieldOutlinePdf(doc, polygonLatLng, x, y, maxW, maxH, opts = {}) {
  const lats = polygonLatLng.map((p) => p[0]);
  const lngs = polygonLatLng.map((p) => p[1]);
  const minLat = Math.min(...lats), maxLat = Math.max(...lats);
  const minLng = Math.min(...lngs), maxLng = Math.max(...lngs);
  const meanLat = (minLat + maxLat) / 2;
  const corte = Math.cos((meanLat * Math.PI) / 180) || 1;
  const latRange = Math.max(maxLat - minLat, 1e-9);
  const lngRangeCorrigido = Math.max((maxLng - minLng) * corte, 1e-9);
  const scale = Math.min(maxW / lngRangeCorrigido, maxH / latRange);
  const wUsed = lngRangeCorrigido * scale, hUsed = latRange * scale;
  const offsetX = x + (maxW - wUsed) / 2, offsetY = y + (maxH - hUsed) / 2;
  const project = ([lat, lng]) => [
    offsetX + (lng - minLng) * corte * scale,
    offsetY + hUsed - (lat - minLat) * scale,
  ];
  const pts = polygonLatLng.map(project);
  const deltas = pts.slice(1).map((p, i) => [p[0] - pts[i][0], p[1] - pts[i][1]]);
  doc.setFillColor(...(opts.fill || [225, 237, 210]));
  doc.setDrawColor(...(opts.stroke || [20, 20, 20]));
  doc.setLineWidth(opts.lineWidth || 0.35);
  doc.lines(deltas, pts[0][0], pts[0][1], [1, 1], opts.filled === false ? "S" : "FD", true);
  return { project, offsetX, offsetY, wUsed, hUsed, scale };
}

// Uma página completa de mapa classificado por nutriente — mesma lógica de
// classificação em faixas já usada na tela (buildHeatOverlay), só que
// renderizada em resolução maior pro PDF, com legenda e caixa de resumo.
function addNutrientMapPage(doc, { polygon, points, nutrientDef, title, areaHa, pageWidth, marginX }) {
  doc.addPage();
  let y = 18;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(11);
  doc.text(title, marginX, y);
  y += 8;

  const overlay = buildHeatOverlay(polygon, points, nutrientDef.key, 260);
  const contentWidth = pageWidth - marginX * 2;
  if (!overlay) {
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9.5);
    doc.setTextColor(120);
    doc.text("Sem dados suficientes pra gerar o mapa desse nutriente.", marginX, y);
    doc.setTextColor(0);
    return;
  }

  const [[minLat, minLng], [maxLat, maxLng]] = overlay.bounds;
  const meanLat = (minLat + maxLat) / 2;
  const corte = Math.cos((meanLat * Math.PI) / 180) || 1;
  const realW = Math.max((maxLng - minLng) * corte, 1e-9), realH = Math.max(maxLat - minLat, 1e-9);
  const mapMaxH = 145;
  const scale = Math.min(contentWidth / realW, mapMaxH / realH);
  const imgW = realW * scale, imgH = realH * scale;
  const imgX = marginX + (contentWidth - imgW) / 2;
  doc.setDrawColor(210);
  doc.setLineWidth(0.3);
  doc.rect(imgX, y, imgW, imgH, "S");
  doc.addImage(overlay.dataUrl, "PNG", imgX, y, imgW, imgH);
  y += imgH + 9;

  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.setTextColor(20);
  doc.text("Legenda", marginX, y);
  y += 2;
  doc.setDrawColor(220);
  doc.line(marginX, y, pageWidth - marginX, y);
  y += 7;
  const legW = contentWidth / overlay.numClasses;
  for (let i = 0; i < overlay.numClasses; i++) {
    const cx = marginX + i * legW;
    const [r, g, b] = overlay.classColors[i];
    doc.setFillColor(r, g, b);
    doc.circle(cx + 2.5, y - 1.3, 1.6, "F");
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.3);
    doc.setTextColor(20);
    doc.text(`${overlay.breaks[i].toFixed(1)} - ${overlay.breaks[i + 1].toFixed(1)}`, cx + 6, y);
    const areaHaClass = overlay.totalCount > 0 ? (overlay.classCounts[i] / overlay.totalCount) * areaHa : 0;
    const pct = overlay.totalCount > 0 ? (overlay.classCounts[i] / overlay.totalCount) * 100 : 0;
    doc.setFontSize(6.8);
    doc.setTextColor(130);
    doc.text(`${areaHaClass.toLocaleString("pt-BR", { maximumFractionDigits: 2 })} ha - ${pct.toFixed(2)}%`, cx + 6, y + 4);
  }
  y += 15;

  const boxH = 26;
  doc.setDrawColor(210);
  doc.setLineWidth(0.3);
  doc.rect(marginX, y, contentWidth, boxH, "S");
  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  doc.setTextColor(20);
  doc.text("Informações", marginX + 4, y + 6);
  doc.setDrawColor(220);
  doc.line(marginX, y + 9, marginX + contentWidth, y + 9);
  doc.setFont("helvetica", "normal");
  doc.setFontSize(8.5);
  const unit = nutrientDef.unit ? ` ${nutrientDef.unit}` : "";
  doc.text(`Área: ${areaHa.toLocaleString("pt-BR", { maximumFractionDigits: 2 })} ha`, marginX + 4, y + 16);
  doc.text(`Mínima: ${overlay.minV.toFixed(1)}${unit}`, marginX + 4, y + 22);
  doc.text(`Média: ${overlay.avgV.toFixed(1)}${unit}`, marginX + 70, y + 16);
  doc.text(`Máxima: ${overlay.maxV.toFixed(1)}${unit}`, marginX + 70, y + 22);
  doc.setTextColor(0);
}

function downloadSoilAnalysisPdf(field, form, desiredV, npk) {
  const doc = new jsPDF();
  const pageWidth = doc.internal.pageSize.getWidth();
  const marginX = 14;
  let y = 18;

  const polygon = field.fieldMap?.mode === "kml" ? field.fieldMap.points : [];
  const areaHa = fieldAreaHa(field);

  doc.setFont("helvetica", "bold");
  doc.setFontSize(15);
  doc.text("Relatório de Análise de Solo", 14, y);
  y += 8;

  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text(`Cliente: ${field.clientName || "—"}`, 14, y); y += 5;
  if (field.clientCpfCnpj) {
    doc.text(`${tipoCpfCnpj(field.clientCpfCnpj)}: ${field.clientCpfCnpj}`, 14, y); y += 5;
  }
  doc.text(`Propriedade: ${field.propertyName || "—"}`, 14, y); y += 5;
  doc.text(`Talhão: ${field.name} (${fieldAreaHa(field).toLocaleString("pt-BR")} ha)`, 14, y); y += 5;
  doc.text(`Data da coleta: ${fmtDate(form.date)}${form.label ? " · " + form.label : ""} · ${form.points.length} ponto(s)`, 14, y);
  y += 9;

  // Mapa do talhão (contorno + área), igual à primeira seção de um "livro" de
  // mapas — só entra quando o talhão tem um polígono desenhado (modo KML).
  if (polygon.length >= 3) {
    doc.addPage();
    let py = 18;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.text("Mapa do Talhão", marginX, py);
    py += 8;
    const contentWidth = pageWidth - marginX * 2;
    const { project } = drawFieldOutlinePdf(doc, polygon, marginX, py, contentWidth, 200);
    const [labelX, labelY] = project([
      polygon.reduce((s, p) => s + p[0], 0) / polygon.length,
      polygon.reduce((s, p) => s + p[1], 0) / polygon.length,
    ]);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(40);
    doc.text(`${field.name}`, labelX, labelY - 2, { align: "center" });
    doc.text(`${areaHa.toLocaleString("pt-BR", { maximumFractionDigits: 2 })} ha`, labelX, labelY + 2, { align: "center" });
    doc.setTextColor(0);

    // Mapa dos pontos de coleta, no mesmo contorno.
    doc.addPage();
    py = 18;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(11);
    doc.text("Mapa dos Pontos de Coleta", marginX, py);
    py += 8;
    const pointsProj = drawFieldOutlinePdf(doc, polygon, marginX, py, contentWidth, 200, { fill: [255, 255, 255] });
    doc.setFillColor(20, 20, 20);
    form.points.forEach((p) => {
      const [px, py2] = pointsProj.project([p.lat, p.lng]);
      doc.circle(px, py2, 0.9, "F");
    });
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(90);
    doc.text(`${form.points.length} ponto(s) de coleta`, marginX, py + 205);
    doc.setTextColor(0);
  }

  doc.addPage();
  y = 18;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.text("Resultados de laboratório por ponto", 14, y);
  y += 2;

  const nutrientCols = SOIL_NUTRIENTS.map((n) => n.label.replace(/\s*\([^)]*\)/, ""));
  autoTable(doc, {
    startY: y + 4,
    head: [["Ponto", ...nutrientCols]],
    body: form.points.map((p) => [
      p.label,
      ...SOIL_NUTRIENTS.map((n) => (p[n.key] !== undefined && p[n.key] !== "" && !Number.isNaN(Number(p[n.key])) ? Number(p[n.key]).toFixed(1) : "—")),
    ]),
    foot: [["Média", ...SOIL_NUTRIENTS.map((n) => {
      const values = form.points
        .filter((p) => p[n.key] !== undefined && p[n.key] !== "")
        .map((p) => Number(p[n.key]))
        .filter((v) => !Number.isNaN(v));
      return values.length ? (values.reduce((s, v) => s + v, 0) / values.length).toFixed(1) : "—";
    })]],
    styles: { fontSize: 7 },
    headStyles: { fillColor: [30, 74, 32] },
    footStyles: { fillColor: [40, 40, 40], fontStyle: "bold" },
  });
  y = doc.lastAutoTable.finalY + 10;

  // Uma página de mapa classificado por nutriente, só pros que têm dado —
  // mesma lógica de faixas/cores já usada na tela de Visualização.
  if (polygon.length >= 3) {
    SOIL_NUTRIENTS.forEach((n) => {
      const hasData = form.points.some((p) => p[n.key] !== undefined && p[n.key] !== "" && !Number.isNaN(Number(p[n.key])));
      if (!hasData) return;
      addNutrientMapPage(doc, {
        polygon, points: form.points, nutrientDef: n,
        title: `${n.label} — ${field.name}`, areaHa, pageWidth, marginX,
      });
    });
  }

  doc.addPage();
  y = 20;
  doc.setFont("helvetica", "bold");
  doc.setFontSize(12);
  doc.text(`Recomendação de Calcário (saturação de bases desejada: ${desiredV}%)`, 14, y);
  y += 2;

  const ncByPoint = form.points.map((p) => ({ p, nc: limeNeedTonPerHa(p, Number(desiredV)) }));
  autoTable(doc, {
    startY: y + 4,
    head: [["Ponto", "V% atual", "CTC (cmolc/dm³)", "Necessidade (t/ha)"]],
    body: ncByPoint.map(({ p, nc }) => [
      p.label,
      p.v !== undefined && p.v !== "" ? Number(p.v).toFixed(1) : "—",
      p.ctc !== undefined && p.ctc !== "" ? Number(p.ctc).toFixed(1) : "—",
      nc !== null ? nc.toFixed(2) : "—",
    ]),
    styles: { fontSize: 8 },
    headStyles: { fillColor: [30, 74, 32] },
  });
  y = doc.lastAutoTable.finalY + 8;

  const ncValues = ncByPoint.map(({ nc }) => nc).filter((v) => v !== null);
  const avgNc = ncValues.length ? ncValues.reduce((s, v) => s + v, 0) / ncValues.length : 0;
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.text(`Necessidade média de calcário: ${avgNc.toFixed(2)} t/ha`, 14, y); y += 5;
  doc.text(`Volume total estimado para o talhão (${areaHa.toLocaleString("pt-BR")} ha): ${(avgNc * areaHa).toFixed(1)} toneladas`, 14, y); y += 5;
  doc.setFontSize(8);
  doc.text("Cálculo pelo método da saturação por bases (NC = CTC x (V desejado - V atual) / 100), considerando calcário com PRNT 100%.", 14, y);
  y += 12;

  if (npk) {
    if (y > 250) { doc.addPage(); y = 20; }
    const cropLabel = NPK_CROPS.find((c) => c.key === npk.crop)?.label || npk.crop;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text(`Recomendação de Adubação NPK (${cropLabel} · produtividade esperada: ${npk.yieldGoal} t/ha)`, 14, y);
    y += 8;

    const doseN = npkDoseKgPerHa(npk.yieldGoal, npk.exportN);
    const doseP = npkDoseKgPerHa(npk.yieldGoal, npk.exportP);
    const doseK = npkDoseKgPerHa(npk.yieldGoal, npk.exportK);
    autoTable(doc, {
      startY: y,
      head: [["Nutriente", "Exportação (kg/ton)", "Dose (kg/ha)", "Total no talhão (kg)"]],
      body: [
        ["N", npk.exportN, doseN !== null ? doseN.toFixed(1) : "—", doseN !== null ? (doseN * areaHa).toFixed(0) : "—"],
        ["P₂O₅", npk.exportP, doseP !== null ? doseP.toFixed(1) : "—", doseP !== null ? (doseP * areaHa).toFixed(0) : "—"],
        ["K₂O", npk.exportK, doseK !== null ? doseK.toFixed(1) : "—", doseK !== null ? (doseK * areaHa).toFixed(0) : "—"],
      ],
      styles: { fontSize: 8 },
      headStyles: { fillColor: [30, 74, 32] },
    });
    y = doc.lastAutoTable.finalY + 8;

    const avgP = avgNutrient(form.points, "p_mel") ?? avgNutrient(form.points, "p_res") ?? avgNutrient(form.points, "p");
    const avgK = avgNutrient(form.points, "k");
    doc.setFont("helvetica", "normal");
    doc.setFontSize(9);
    doc.text(`Fósforo médio no talhão: ${avgP !== null ? avgP.toFixed(1) + " mg/dm³" : "—"} · Potássio médio no talhão: ${avgK !== null ? avgK.toFixed(1) + " mg/dm³" : "—"}`, 14, y);
    y += 5;
    doc.setFontSize(8);
    doc.text("Cálculo pelo método de reposição/exportação (dose = exportação por tonelada x produtividade esperada). Coeficientes de referência, ajustáveis conforme calibração regional.", 14, y);
  }

  const pageHeightFinal = doc.internal.pageSize.getHeight();
  const pageCountFinal = doc.internal.getNumberOfPages();
  for (let i = 1; i <= pageCountFinal; i++) {
    doc.setPage(i);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    doc.setTextColor(150);
    doc.text(`Gerado em ${fmtDateTime(new Date().toISOString())} · Semear Consultoria Agropecuária`, marginX, pageHeightFinal - 10);
    doc.text(`Pág. ${i}/${pageCountFinal}`, pageWidth - marginX, pageHeightFinal - 10, { align: "right" });
  }
  doc.setTextColor(0);

  const safeName = `${field.name}`.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-zA-Z0-9]/g, "_");
  doc.save(`analise-solo-${safeName}-${form.date}.pdf`);
}

function generateSamplingGrid(polygon, hectaresPerPoint) {
  const lats = polygon.map((p) => p[0]);
  const lngs = polygon.map((p) => p[1]);
  const minLat = Math.min(...lats), maxLat = Math.max(...lats);
  const minLng = Math.min(...lngs), maxLng = Math.max(...lngs);
  const meanLat = (minLat + maxLat) / 2;

  const spacingM = Math.sqrt(Math.max(hectaresPerPoint, 0.1) * 10000);
  const latStep = spacingM / 111320;
  const lngStep = spacingM / (111320 * Math.cos((meanLat * Math.PI) / 180));

  const points = [];
  for (let lat = minLat + latStep / 2; lat <= maxLat; lat += latStep) {
    for (let lng = minLng + lngStep / 2; lng <= maxLng; lng += lngStep) {
      if (pointInPolygon(lat, lng, polygon)) {
        points.push({ id: uid(), lat, lng, label: `P${points.length + 1}` });
      }
    }
  }
  return points;
}

function haversineMeters(lat1, lng1, lat2, lng2) {
  const R = 6371000;
  const toRad = (d) => (d * Math.PI) / 180;
  const dLat = toRad(lat2 - lat1);
  const dLng = toRad(lng2 - lng1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function SoilAnalysisPage({ data, field, readOnly, initialStep, onSave, onBack, onClose }) {
  const [form, setForm] = useState({
    id: data?.id || uid(), fieldId: field.id, date: new Date().toISOString().slice(0, 10),
    label: "", points: [],
    ...(data || {}),
  });
  const [step, setStep] = useState(initialStep || (readOnly ? "visualizacao" : "coleta"));
  const [selectedPointId, setSelectedPointId] = useState(form.points[0]?.id || null);
  const [nutrient, setNutrient] = useState("p");
  const [soilDepth, setSoilDepth] = useState("0-20");
  const [showDeepPoint, setShowDeepPoint] = useState(false);
  const [desiredV, setDesiredV] = useState(70);
  const [exporting, setExporting] = useState(false);
  const [exportError, setExportError] = useState("");
  const isLimeMode = nutrient === "nc_calcario";
  const isNpkMode = nutrient === "npk";
  const [npkCrop, setNpkCrop] = useState("soja");
  const [npkYieldGoal, setNpkYieldGoal] = useState(3.5);
  const [npkExportN, setNpkExportN] = useState(NPK_CROPS[0].n);
  const [npkExportP, setNpkExportP] = useState(NPK_CROPS[0].p2o5);
  const [npkExportK, setNpkExportK] = useState(NPK_CROPS[0].k2o);
  function handleNpkCropChange(cropKey) {
    setNpkCrop(cropKey);
    const crop = NPK_CROPS.find((c) => c.key === cropKey);
    if (crop) { setNpkExportN(crop.n); setNpkExportP(crop.p2o5); setNpkExportK(crop.k2o); }
  }
  const [gridHectares, setGridHectares] = useState(5);
  const [gridError, setGridError] = useState("");
  const [gpsActive, setGpsActive] = useState(false);
  const [liveLocation, setLiveLocation] = useState(null);
  const [gpsError, setGpsError] = useState("");
  const [fullscreen, setFullscreen] = useState(false);
  const [detailsOpen, setDetailsOpen] = useState(false);
  const [importSummary, setImportSummary] = useState("");
  const [importError, setImportError] = useState("");
  const [ndviLoading, setNdviLoading] = useState(false);
  const [ndviError, setNdviError] = useState("");
  const [ndviGrid, setNdviGrid] = useState(null);
  const [ndviOverlay, setNdviOverlay] = useState(null);
  const [ndviDateRangeUsed, setNdviDateRangeUsed] = useState(null);
  const [ndviZones, setNdviZones] = useState(null);
  const [ndviHectaresPerZone, setNdviHectaresPerZone] = useState(15);
  const [ndviPointsPerZone, setNdviPointsPerZone] = useState(2);
  const [ndviShowLayer, setNdviShowLayer] = useState(true);
  const [ndviDateTo, setNdviDateTo] = useState(() => new Date().toISOString().slice(0, 10));
  const [ndviDateFrom, setNdviDateFrom] = useState(() => new Date(Date.now() - 45 * 86400000).toISOString().slice(0, 10));
  const [overlayOpacity, setOverlayOpacity] = useState(0.65);
  const watchIdRef = useRef(null);

  const polygon = field.fieldMap?.mode === "kml" ? field.fieldMap.points : [];
  const bounds = polygon.length >= 3 ? polygon.map(([lat, lng]) => [lat, lng]) : null;
  const fieldAreaHaValue = useMemo(
    () => (polygon.length >= 3 ? geodesicAreaHa(polygon.map(([lat, lng]) => ({ lat, lng }))) : 0),
    [polygon]
  );

  function switchStep(next) {
    setStep(next);
    if (next === "insumos" && !isLimeMode && !isNpkMode) setNutrient("nc_calcario");
    if (next === "visualizacao" && (isLimeMode || isNpkMode)) setNutrient("p");
  }

  useEffect(() => {
    return () => { if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current); };
  }, []);

  function toggleGps() {
    if (gpsActive) {
      if (watchIdRef.current !== null) navigator.geolocation.clearWatch(watchIdRef.current);
      watchIdRef.current = null;
      setGpsActive(false);
      setLiveLocation(null);
      return;
    }
    if (!navigator.geolocation) {
      setGpsError("Esse navegador/dispositivo não tem suporte a GPS.");
      return;
    }
    setGpsError("");
    watchIdRef.current = navigator.geolocation.watchPosition(
      (pos) => setLiveLocation({ lat: pos.coords.latitude, lng: pos.coords.longitude }),
      (err) => setGpsError(err.message || "Não foi possível obter sua localização. Confira se o navegador tem permissão de GPS."),
      { enableHighAccuracy: true, maximumAge: 2000, timeout: 15000 }
    );
    setGpsActive(true);
  }

  const sortedPoints = useMemo(() => {
    if (!liveLocation) return form.points;
    return [...form.points].sort(
      (a, b) => haversineMeters(liveLocation.lat, liveLocation.lng, a.lat, a.lng) - haversineMeters(liveLocation.lat, liveLocation.lng, b.lat, b.lng)
    );
  }, [form.points, liveLocation]);

  function handleMapClick(lat, lng) {
    if (readOnly || step !== "coleta") return;
    const label = `P${form.points.length + 1}`;
    const point = { id: uid(), lat, lng, label };
    setForm((f) => ({ ...f, points: [...f.points, point] }));
    setSelectedPointId(point.id);
  }

  function handleGenerateGrid() {
    setGridError("");
    if (!bounds) return;
    if (form.points.length > 0 && !confirm(`Isso substitui os ${form.points.length} ponto(s) já existentes (e qualquer resultado já preenchido). Continuar?`)) {
      return;
    }
    const generated = generateSamplingGrid(polygon, Number(gridHectares) || 5);
    if (generated.length === 0) {
      setGridError("Nenhum ponto coube dentro do talhão com esse espaçamento. Tente um valor menor.");
      return;
    }
    if (generated.length > 500) {
      setGridError(`Isso geraria ${generated.length} pontos — tente um espaçamento maior (menos denso).`);
      return;
    }
    setForm((f) => ({ ...f, points: generated }));
    setSelectedPointId(null);
  }

  async function handleImportFile(file) {
    setImportError("");
    setImportSummary("");
    try {
      const { rows, mapping } = await parseSoilSpreadsheet(file);
      if (mapping.label === undefined) {
        setImportError('Não encontrei uma coluna de identificação do ponto (ex: "Ponto", "Amostra", "ID") na planilha.');
        return;
      }
      if (rows.length === 0) {
        setImportError("Não encontrei nenhuma linha de dado na planilha.");
        return;
      }
      let updated = 0;
      const notFound = [];
      const nextPoints = form.points.map((p) => ({ ...p }));
      rows.forEach((row) => {
        if (!row.label) return;
        const point = nextPoints.find((p) => p.label.trim().toLowerCase() === row.label.trim().toLowerCase());
        if (!point) { notFound.push(row.label); return; }
        // Itera as chaves que a planilha realmente trouxe (row), não as chaves-base de
        // SOIL_COLUMN_ALIASES — senão as colunas de 20-40cm (que viram "<nutriente>_20_40",
        // uma chave que não existe em SOIL_COLUMN_ALIASES) ficariam de fora silenciosamente.
        Object.keys(row).forEach((key) => {
          if (key === "label") return;
          if (row[key] !== undefined && row[key] !== null && !Number.isNaN(row[key])) {
            point[key] = row[key];
          }
        });
        updated++;
      });
      setForm((f) => ({ ...f, points: nextPoints }));
      setImportSummary(
        `${updated} ponto(s) atualizado(s) a partir da planilha.` +
        (notFound.length > 0 ? ` ${notFound.length} linha(s) sem ponto correspondente no mapa (${notFound.slice(0, 5).join(", ")}${notFound.length > 5 ? "…" : ""}).` : "")
      );
    } catch (e) {
      setImportError("Não consegui ler esse arquivo. Confira se é um .xlsx, .xls ou .csv válido, exportado de uma planilha.");
    }
  }

  async function handleFetchNdviPreview() {
    setNdviError("");
    setNdviLoading(true);
    setNdviZones(null);
    setNdviOverlay(null);
    setNdviGrid(null);
    setNdviDateRangeUsed(null);
    try {
      if (ndviDateFrom && ndviDateTo && ndviDateFrom >= ndviDateTo) {
        setNdviError("A data de início precisa ser antes da data de fim.");
        return;
      }
      const lats = polygon.map((p) => p[0]);
      const lngs = polygon.map((p) => p[1]);
      const bbox = [Math.min(...lngs), Math.min(...lats), Math.max(...lngs), Math.max(...lats)];
      const r = await fetchNdvi({ bbox, dateFrom: ndviDateFrom, dateTo: ndviDateTo });
      if (r.error) { setNdviError(r.error); return; }
      const { image, bounds: imgBounds, width, height, dateRange } = r.data;
      const grid = await decodeNdviGrid(image, width, height);
      const overlay = buildNdviOverlayImage(grid, imgBounds);
      if (!overlay) {
        setNdviError("A imagem voltou sem nenhum pixel válido (provavelmente nuvem cobrindo o talhão o período todo). Tenta um período diferente.");
        return;
      }
      setNdviGrid({ grid, bounds: imgBounds });
      setNdviOverlay(overlay);
      setNdviDateRangeUsed(dateRange);
    } catch (e) {
      setNdviError(e.message || "Não consegui buscar a imagem NDVI.");
    } finally {
      setNdviLoading(false);
    }
  }

  function ndviNumClassesFor(hectaresPerZone) {
    if (!fieldAreaHaValue) return 4;
    return Math.max(2, Math.min(8, Math.round(fieldAreaHaValue / (Number(hectaresPerZone) || 15)) || 2));
  }

  function handleClassifyNdvi() {
    if (!ndviGrid) return;
    setNdviZones(classifyNdviZones(polygon, ndviGrid.bounds, ndviGrid.grid, ndviNumClassesFor(ndviHectaresPerZone)));
  }

  function handleReclassifyNdvi(newHectaresPerZone) {
    setNdviHectaresPerZone(newHectaresPerZone);
    if (!ndviGrid) return;
    setNdviZones(classifyNdviZones(polygon, ndviGrid.bounds, ndviGrid.grid, ndviNumClassesFor(newHectaresPerZone)));
  }

  function handleGenerateGridFromNdvi() {
    if (!ndviZones || ndviZones.zones.length === 0) return;
    if (form.points.length > 0 && !confirm(`Isso substitui os ${form.points.length} ponto(s) já existentes (e qualquer resultado já preenchido). Continuar?`)) {
      return;
    }
    let allPoints = [];
    ndviZones.zones.forEach((zone) => {
      allPoints = allPoints.concat(generatePointsForZone(zone, Number(ndviPointsPerZone) || 1));
    });
    const relabeled = allPoints.map((p, i) => ({ ...p, label: `P${i + 1}` }));
    setForm((f) => ({ ...f, points: relabeled }));
    setSelectedPointId(null);
  }

  async function handleExportNdviZones() {
    setNdviError("");
    if (!ndviZones || ndviZones.zones.length === 0) return;
    try {
      const features = [];
      ndviZones.zones.forEach((zone) => {
        zone.polygons.forEach((polyRings) => {
          features.push({
            type: "Feature",
            properties: { ZONA: zone.classIndex + 1, NDVI_MED: Number(zone.ndviAvg.toFixed(3)) },
            geometry: { type: "Polygon", coordinates: polyRings },
          });
        });
      });
      await downloadShapefileZip({ type: "FeatureCollection", features }, "zonas_ndvi", field);
    } catch (e) {
      setNdviError(e.message || "Não consegui exportar as zonas.");
    }
  }

  function updateSelectedPoint(patch) {
    setForm((f) => ({ ...f, points: f.points.map((p) => (p.id === selectedPointId ? { ...p, ...patch } : p)) }));
  }

  function deletePoint(id) {
    setForm((f) => ({ ...f, points: f.points.filter((p) => p.id !== id) }));
    if (selectedPointId === id) setSelectedPointId(null);
  }

  const selectedPoint = form.points.find((p) => p.id === selectedPointId);
  const showHeatMap = step !== "coleta";
  // Só faz sentido escolher profundidade quando é um nutriente de verdade (não
  // no modo calcário nem NPK, que não têm camada).
  const effectiveNutrientKey = !isLimeMode && !isNpkMode ? soilDepthKey(nutrient, soilDepth) : nutrient;
  const pointValue = (p) => (isLimeMode ? limeNeedTonPerHa(p, Number(desiredV)) : p[effectiveNutrientKey] !== undefined && p[effectiveNutrientKey] !== "" ? Number(p[effectiveNutrientKey]) : null);
  const heatOverlay = useMemo(() => {
    if (!showHeatMap) return null;
    if (isLimeMode) {
      const withLime = form.points.map((p) => ({ ...p, __lime: limeNeedTonPerHa(p, Number(desiredV)) }));
      return buildHeatOverlay(polygon, withLime, "__lime");
    }
    return buildHeatOverlay(polygon, form.points, effectiveNutrientKey);
  }, [polygon, form.points, effectiveNutrientKey, isLimeMode, desiredV, showHeatMap]);
  const canSave = !readOnly && form.date && form.points.length >= 3;

  async function handleExportShp() {
    setExportError("");
    setExporting(true);
    try {
      const depthSuffix = !isLimeMode && !isNpkMode && soilDepth === "20-40" ? "_2040" : "";
      const fieldName = isLimeMode ? "RATE" : (nutrient.toUpperCase() + depthSuffix);
      const prefix = isLimeMode ? "calcario" : (nutrient + depthSuffix);
      await downloadPrescriptionShapefile(field, form.points, fieldName, pointValue, prefix);
    } catch (e) {
      setExportError(e.message || "Não consegui gerar o arquivo SHP.");
    } finally {
      setExporting(false);
    }
  }

  const mapEl = bounds && (
    <MapContainer bounds={bounds} boundsOptions={{ padding: [16, 16] }} style={{ height: "100%", width: "100%" }} scrollWheelZoom>
      <LayersControl position="topright">
        <LayersControl.BaseLayer checked name="Satélite">
          <TileLayer
            attribution="Tiles &copy; Esri — Source: Esri, Maxar, Earthstar Geographics"
            url="https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}"
            maxZoom={19}
          />
        </LayersControl.BaseLayer>
        <LayersControl.BaseLayer name="Ruas">
          <TileLayer
            attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
            url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            maxZoom={19}
          />
        </LayersControl.BaseLayer>
        <LayersControl.BaseLayer name="Branco">
          <TileLayer attribution="" url={WHITE_TILE_URL} maxZoom={19} />
        </LayersControl.BaseLayer>
      </LayersControl>
      <Polygon positions={bounds} pathOptions={{ color: "#7BC142", weight: 1.5, fillOpacity: 0 }} />
      {heatOverlay && <ImageOverlay url={heatOverlay.dataUrl} bounds={heatOverlay.bounds} opacity={overlayOpacity} />}
      {step === "coleta" && ndviShowLayer && !ndviZones && ndviOverlay && (
        <ImageOverlay url={ndviOverlay.dataUrl} bounds={ndviOverlay.bounds} opacity={overlayOpacity} />
      )}
      {step === "coleta" && ndviShowLayer && ndviZones && ndviZones.zones.map((zone) => {
        const t = ndviZones.zones.length > 1 ? zone.classIndex / (ndviZones.zones.length - 1) : 0.5;
        const [r, g, b] = ndviColor(t);
        // Zonas de NDVI podem virar vários pedaços desconectados depois do union — rotula
        // só o maior pedaço de cada zona, senão o rótulo "Zona N" se repete em cada
        // fragmento pequeno e polui o mapa.
        const largestIdx = zone.polygons.reduce((best, polyRings, i) => {
          const ring = polyRings[0];
          let area = 0;
          for (let k = 0; k < ring.length - 1; k++) area += ring[k][0] * ring[k + 1][1] - ring[k + 1][0] * ring[k][1];
          area = Math.abs(area) / 2;
          return area > best.area ? { i, area } : best;
        }, { i: 0, area: -1 }).i;
        return (
          <React.Fragment key={zone.classIndex}>
            {zone.polygons.map((polyRings, i) => (
              <Polygon
                key={i}
                positions={polyRings[0].map(([lng, lat]) => [lat, lng])}
                pathOptions={{ color: `rgb(${r},${g},${b})`, weight: 1, fillColor: `rgb(${r},${g},${b})`, fillOpacity: overlayOpacity }}
              >
                {i === largestIdx && <Tooltip permanent direction="center" className="soil-value-label">Zona {zone.classIndex + 1}</Tooltip>}
              </Polygon>
            ))}
          </React.Fragment>
        );
      })}
      {!readOnly && step === "coleta" && <MapClickCapture onClick={handleMapClick} />}
      {form.points.map((p) => {
        const val = pointValue(p);
        const hasValue = val !== null && !Number.isNaN(val);
        const showValue = !!heatOverlay && hasValue;
        const isSelected = selectedPointId === p.id;
        return (
          <CircleMarker
            key={p.id}
            center={[p.lat, p.lng]}
            radius={isSelected ? 10 : showValue ? 9 : 7}
            pathOptions={{
              color: isSelected ? "#0E1310" : "transparent",
              weight: isSelected ? 2.5 : 0,
              fillColor: showValue ? "transparent" : hasValue ? "#F2F0E6" : "#9BA298",
              fillOpacity: showValue ? 0 : 0.9,
            }}
            eventHandlers={{ click: () => setSelectedPointId(p.id) }}
          >
            <Tooltip permanent direction="top" offset={[0, showValue ? -4 : -9]} className={showValue ? "soil-value-label" : "field-map-label"}>
              {showValue ? val.toFixed(1) : p.label}
            </Tooltip>
          </CircleMarker>
        );
      })}
      {liveLocation && (
        <CircleMarker
          center={[liveLocation.lat, liveLocation.lng]}
          radius={8}
          pathOptions={{ color: "#F5F2E8", weight: 2, fillColor: "#2E86FF", fillOpacity: 0.9 }}
        >
          <Tooltip direction="top" permanent>Você está aqui</Tooltip>
        </CircleMarker>
      )}
    </MapContainer>
  );

  const heatUnit = isLimeMode ? "t/ha" : SOIL_NUTRIENTS.find((n) => n.key === nutrient)?.unit || "";
  const legendEl = heatOverlay && (
    <div style={{
      position: "absolute", bottom: 10, right: 10, zIndex: 1000,
      background: "rgba(14,19,16,0.92)", border: "1px solid #232B25", borderRadius: 8,
      padding: "9px 11px", fontSize: 9, color: "#D6D3C7", minWidth: 175,
    }}>
      <div style={{ fontWeight: 600, marginBottom: 6, whiteSpace: "nowrap" }}>
        {isLimeMode ? "Necessidade de Calcário (t/ha)" : SOIL_NUTRIENTS.find((n) => n.key === nutrient)?.label}
      </div>
      {heatOverlay.classColors.map((c, i) => {
        if (heatOverlay.classCounts[i] === 0) return null;
        const areaHa = heatOverlay.totalCount > 0 ? (heatOverlay.classCounts[i] / heatOverlay.totalCount) * fieldAreaHaValue : 0;
        const pct = heatOverlay.totalCount > 0 ? (heatOverlay.classCounts[i] / heatOverlay.totalCount) * 100 : 0;
        return (
          <div key={i} style={{ display: "flex", alignItems: "center", gap: 6, marginBottom: 3, fontFamily: "'IBM Plex Mono', monospace", whiteSpace: "nowrap" }}>
            <span style={{ width: 10, height: 10, borderRadius: 2, background: `rgb(${c[0]},${c[1]},${c[2]})`, flexShrink: 0 }} />
            <span>{heatOverlay.breaks[i].toFixed(1)}–{heatOverlay.breaks[i + 1].toFixed(1)}</span>
            <span style={{ color: "#6B7268", marginLeft: "auto" }}>{areaHa.toFixed(1)}ha · {pct.toFixed(0)}%</span>
          </div>
        );
      })}
    </div>
  );

  const statsEl = heatOverlay && (
    <div style={{
      position: "absolute", bottom: 10, left: 10, zIndex: 1000,
      background: "rgba(14,19,16,0.92)", border: "1px solid #232B25", borderRadius: 8,
      padding: "9px 11px", fontSize: 9, color: "#D6D3C7", minWidth: 130,
    }}>
      <div style={{ fontWeight: 600, marginBottom: 6 }}>Resumo</div>
      <div style={{ display: "grid", gridTemplateColumns: "auto auto", gap: "3px 12px", fontFamily: "'IBM Plex Mono', monospace" }}>
        <span style={{ color: "#6B7268" }}>Área do talhão</span><span>{fieldAreaHaValue.toFixed(1)} ha</span>
        {isLimeMode && (
          <>
            <span style={{ color: "#6B7268" }}>Total necessário</span>
            <span>{(heatOverlay.avgV * fieldAreaHaValue).toFixed(1)} t</span>
          </>
        )}
        <span style={{ color: "#6B7268" }}>Média</span><span>{heatOverlay.avgV.toFixed(1)} {heatUnit}</span>
        <span style={{ color: "#6B7268" }}>Mínima</span><span>{heatOverlay.minV.toFixed(1)} {heatUnit}</span>
        <span style={{ color: "#6B7268" }}>Máxima</span><span>{heatOverlay.maxV.toFixed(1)} {heatUnit}</span>
      </div>
    </div>
  );

  const hasColorOverlay = !!heatOverlay || (step === "coleta" && (!!ndviOverlay || !!ndviZones));
  const opacitySliderEl = hasColorOverlay && (
    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
      <Volume2 size={14} color="#9BA298" />
      <input
        type="range" min="0.1" max="1" step="0.05" value={overlayOpacity}
        onChange={(e) => setOverlayOpacity(Number(e.target.value))}
        style={{ width: 110 }}
        title="Transparência das cores no mapa"
      />
    </div>
  );

  const coletaControlsEl = (
    <>
      {!readOnly && (
        <div style={{ display: "flex", gap: 8, alignItems: "center", marginBottom: 12, flexWrap: "wrap" }}>
          <GhostBtn onClick={toggleGps}>
            <MapPin size={14} /> {gpsActive ? "Desativar GPS ao vivo" : "Ativar GPS ao vivo"}
          </GhostBtn>
          {gpsError && <span style={{ fontSize: 9.5, color: "#E38B84" }}>{gpsError}</span>}
        </div>
      )}
      {gpsActive && (
        <div style={{ fontSize: 9.5, color: "#6B7268", marginBottom: 8 }}>
          {liveLocation ? "Pontos ordenados do mais perto pro mais longe da sua posição atual." : "Localizando…"}
        </div>
      )}

      <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginBottom: 14 }}>
        {sortedPoints.map((p) => {
          const dist = liveLocation ? Math.round(haversineMeters(liveLocation.lat, liveLocation.lng, p.lat, p.lng)) : null;
          return (
            <button key={p.id} onClick={() => setSelectedPointId(p.id)} style={{
              display: "flex", alignItems: "center", gap: 5, padding: "5px 10px", borderRadius: 16,
              border: "1px solid " + (selectedPointId === p.id ? "#3E7A3F" : "#232B25"),
              background: selectedPointId === p.id ? "#1E4A20" : "#161D19",
              color: selectedPointId === p.id ? "#F5F2E8" : "#D6D3C7", fontSize: 10, cursor: "pointer",
            }}>
              {p.label}{dist !== null ? ` · ${dist}m` : ""}
              {!readOnly && (
                <X size={11} onClick={(e) => { e.stopPropagation(); deletePoint(p.id); }} />
              )}
            </button>
          );
        })}
        {form.points.length === 0 && <span style={{ fontSize: 10, color: "#6B7268" }}>Nenhum ponto ainda.</span>}
      </div>

      {selectedPoint && (
        <div style={{ background: "#10140F", border: "1px solid #212922", borderRadius: 8, padding: 14, marginBottom: 14 }}>
          <div style={{ fontSize: 10.5, fontWeight: 600, color: "#D6D3C7", marginBottom: 10 }}>Resultado — {selectedPoint.label}</div>
          <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(120px, 1fr))", gap: 10 }}>
            {SOIL_NUTRIENTS.map((n) => (
              <div key={n.key}>
                <div style={{ fontSize: 9, color: "#6B7268", marginBottom: 3 }}>{n.label}{n.unit ? ` (${n.unit})` : ""}</div>
                {readOnly ? (
                  <div style={{ fontSize: 11, color: "#D6D3C7" }}>{selectedPoint[n.key] ?? "—"}</div>
                ) : (
                  <input
                    type="number" style={inputStyle}
                    value={selectedPoint[n.key] ?? ""}
                    onChange={(e) => updateSelectedPoint({ [n.key]: e.target.value === "" ? "" : Number(e.target.value) })}
                  />
                )}
              </div>
            ))}
          </div>
          {!readOnly && !showDeepPoint && (
            <GhostBtn onClick={() => setShowDeepPoint(true)} style={{ marginTop: 10 }}>
              <Plus size={13} /> Adicionar dados de 20-40cm
            </GhostBtn>
          )}
          {(showDeepPoint || (readOnly && SOIL_NUTRIENTS.some((n) => selectedPoint[soilDepthKey(n.key, "20-40")]))) && (
            <div style={{ marginTop: 12, paddingTop: 12, borderTop: "1px dashed #232B25" }}>
              <div style={{ fontSize: 9.5, color: "#9BA298", marginBottom: 8 }}>Camada 20-40cm</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(120px, 1fr))", gap: 10 }}>
                {SOIL_NUTRIENTS.map((n) => {
                  const deepKey = soilDepthKey(n.key, "20-40");
                  return (
                    <div key={deepKey}>
                      <div style={{ fontSize: 9, color: "#6B7268", marginBottom: 3 }}>{n.label}{n.unit ? ` (${n.unit})` : ""}</div>
                      {readOnly ? (
                        <div style={{ fontSize: 11, color: "#D6D3C7" }}>{selectedPoint[deepKey] ?? "—"}</div>
                      ) : (
                        <input
                          type="number" style={inputStyle}
                          value={selectedPoint[deepKey] ?? ""}
                          onChange={(e) => updateSelectedPoint({ [deepKey]: e.target.value === "" ? "" : Number(e.target.value) })}
                        />
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      )}
    </>
  );

  // Só mostra o seletor de profundidade quando o talhão realmente tem dado de
  // 20-40cm importado — pra não mudar nada da tela pra quem só coleta 0-20cm.
  const hasDeepData = form.points.some((p) =>
    SOIL_NUTRIENTS.some((n) => {
      const v = p[soilDepthKey(n.key, "20-40")];
      return v !== undefined && v !== null && v !== "";
    })
  );
  const visualizacaoControlsEl = (
    <div>
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
        <span style={{ fontSize: 9.5, color: "#9BA298" }}>Nutriente:</span>
        <select style={{ ...inputStyle, width: 220 }} value={nutrient} onChange={(e) => setNutrient(e.target.value)}>
          {SOIL_NUTRIENTS.map((n) => <option key={n.key} value={n.key}>{n.label}</option>)}
        </select>
        {hasDeepData && (
          <>
            <span style={{ fontSize: 9.5, color: "#9BA298" }}>Profundidade:</span>
            <select style={{ ...inputStyle, width: 110 }} value={soilDepth} onChange={(e) => setSoilDepth(e.target.value)}>
              {SOIL_DEPTHS.map((d) => <option key={d.key} value={d.key}>{d.label}</option>)}
            </select>
          </>
        )}
        {form.points.length >= 3 && (
          <GhostBtn onClick={handleExportShp} disabled={exporting}>{exporting ? "Gerando…" : "Exportar SHP"}</GhostBtn>
        )}
        {exportError && <span style={{ fontSize: 9.5, color: "#E38B84" }}>{exportError}</span>}
      </div>
    </div>
  );

  const npkDoseN = npkDoseKgPerHa(npkYieldGoal, npkExportN);
  const npkDoseP = npkDoseKgPerHa(npkYieldGoal, npkExportP);
  const npkDoseK = npkDoseKgPerHa(npkYieldGoal, npkExportK);
  const npkAvgP = avgNutrient(form.points, "p_mel") ?? avgNutrient(form.points, "p_res") ?? avgNutrient(form.points, "p");
  const npkAvgK = avgNutrient(form.points, "k");
  const npkPdfData = { crop: npkCrop, yieldGoal: Number(npkYieldGoal) || 0, exportN: Number(npkExportN) || 0, exportP: Number(npkExportP) || 0, exportK: Number(npkExportK) || 0 };

  const insumosControlsEl = (
    <div>
      <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
        <span style={{ fontSize: 9.5, color: "#9BA298" }}>Insumo:</span>
        <select style={{ ...inputStyle, width: 220 }} value={nutrient} onChange={(e) => setNutrient(e.target.value)}>
          <option value="nc_calcario">Necessidade de Calcário (t/ha)</option>
          <option value="npk">Adubação NPK (kg/ha)</option>
        </select>
        {isLimeMode && (
          <>
            <span style={{ fontSize: 9.5, color: "#9BA298" }}>Saturação de bases (V%) desejada:</span>
            <input
              type="number" min="0" max="100" step="1" style={{ ...inputStyle, width: 70 }}
              value={desiredV} onChange={(e) => setDesiredV(e.target.value)}
            />
          </>
        )}
        {!isNpkMode && form.points.length >= 3 && (
          <GhostBtn onClick={handleExportShp} disabled={exporting}>{exporting ? "Gerando…" : "Exportar SHP"}</GhostBtn>
        )}
        {exportError && <span style={{ fontSize: 9.5, color: "#E38B84" }}>{exportError}</span>}
      </div>
      {isNpkMode && (
        <div style={{ marginTop: 12, padding: 12, borderRadius: 8, border: "1px solid #232B25", background: "#171C18" }}>
          <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", marginBottom: 10 }}>
            <span style={{ fontSize: 9.5, color: "#9BA298" }}>Cultura:</span>
            <select style={{ ...inputStyle, width: 160 }} value={npkCrop} onChange={(e) => handleNpkCropChange(e.target.value)}>
              {NPK_CROPS.map((c) => <option key={c.key} value={c.key}>{c.label}</option>)}
            </select>
            <span style={{ fontSize: 9.5, color: "#9BA298" }}>Produtividade esperada (t/ha):</span>
            <input
              type="number" min="0" step="0.1" style={{ ...inputStyle, width: 80 }}
              value={npkYieldGoal} onChange={(e) => setNpkYieldGoal(e.target.value)}
            />
          </div>
          <div style={{ display: "flex", gap: 16, flexWrap: "wrap", marginBottom: 10 }}>
            {[
              { label: "N", exp: npkExportN, setExp: setNpkExportN, dose: npkDoseN },
              { label: "P₂O₅", exp: npkExportP, setExp: setNpkExportP, dose: npkDoseP },
              { label: "K₂O", exp: npkExportK, setExp: setNpkExportK, dose: npkDoseK },
            ].map((n) => (
              <div key={n.label} style={{ display: "flex", flexDirection: "column", gap: 4 }}>
                <span style={{ fontSize: 9.5, color: "#9BA298" }}>{n.label} — exportação (kg/ton)</span>
                <input
                  type="number" min="0" step="0.5" style={{ ...inputStyle, width: 90 }}
                  value={n.exp} onChange={(e) => n.setExp(e.target.value)}
                />
                <span style={{ fontSize: 12, fontWeight: 700, color: "#F2F0E6" }}>
                  {n.dose !== null ? `${n.dose.toFixed(1)} kg/ha` : "—"}
                </span>
              </div>
            ))}
          </div>
          <div style={{ fontSize: 9.5, color: "#9BA298" }}>
            Fósforo médio no talhão: {npkAvgP !== null ? `${npkAvgP.toFixed(1)} mg/dm³` : "—"} · Potássio médio no talhão: {npkAvgK !== null ? `${npkAvgK.toFixed(1)} mg/dm³` : "—"}
          </div>
          <div style={{ fontSize: 8.5, color: "#6E756B", marginTop: 6 }}>
            Método de reposição/exportação (dose = exportação por tonelada x produtividade esperada). Coeficientes de referência — ajuste conforme a calibração da sua região.
          </div>
        </div>
      )}
    </div>
  );

  const stepControlsEl = step === "coleta" ? coletaControlsEl : step === "visualizacao" ? visualizacaoControlsEl : insumosControlsEl;

  const tabsEl = bounds && (
    <div style={{ display: "flex", gap: 8, marginBottom: 14, flexWrap: "wrap" }}>
      {[
        { id: "coleta", label: "1. Importação e coleta", icon: ClipboardList },
        { id: "visualizacao", label: "2. Visualização", icon: Microscope },
        { id: "insumos", label: "3. Recomendação de insumos", icon: FlaskConical },
      ].map((t) => {
        const Icon = t.icon;
        const active = step === t.id;
        return (
          <button key={t.id} onClick={() => switchStep(t.id)} style={{
            display: "flex", alignItems: "center", gap: 7, padding: "7px 14px", borderRadius: 20,
            border: "1px solid " + (active ? "#1E4A20" : "#232B25"),
            background: active ? "#1E4A20" : "#161D19", color: active ? "#F5F2E8" : "#D6D3C7",
            fontSize: 10, fontWeight: 600, cursor: "pointer",
          }}>
            <Icon size={14} /> {t.label}
          </button>
        );
      })}
    </div>
  );

  if (fullscreen && bounds) {
    return (
      <div style={{ position: "fixed", inset: 0, zIndex: 300, background: "#0E1310", display: "flex", flexDirection: "column" }}>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: "12px 16px", borderBottom: "1px solid #232B25", flexShrink: 0, gap: 8, flexWrap: "wrap" }}>
          <div style={{ fontSize: 12, fontWeight: 700, color: "#F2F0E6" }}>{form.label || fmtDate(form.date)}</div>
          <div style={{ display: "flex", gap: 14, alignItems: "center" }}>
            {opacitySliderEl}
            {!readOnly && <PrimaryBtn onClick={() => canSave && onSave(form)} disabled={!canSave}>Salvar</PrimaryBtn>}
            <GhostBtn onClick={() => setFullscreen(false)}><X size={14} /> Sair da tela cheia</GhostBtn>
          </div>
        </div>
        <div style={{ padding: "10px 16px 0" }}>{tabsEl}</div>
        <div style={{ flex: 1, minHeight: 0, position: "relative" }}>{mapEl}{legendEl}{statsEl}</div>
        <div style={{ padding: 14, overflowY: "auto", maxHeight: "42vh", flexShrink: 0, borderTop: "1px solid #232B25" }}>
          {step === "coleta" ? (
            <>
              <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: detailsOpen ? 12 : 0 }}>
                <GhostBtn onClick={() => setDetailsOpen((v) => !v)}>
                  {detailsOpen ? "Ocultar controles" : "Mais controles"}
                </GhostBtn>
              </div>
              {detailsOpen && coletaControlsEl}
            </>
          ) : (
            stepControlsEl
          )}
        </div>
      </div>
    );
  }

  const bodyEl = (
    <>
      {!onBack && (
        <div style={{ display: "flex", gap: 12, marginBottom: 12, flexWrap: "wrap" }}>
          <div style={{ flex: 1, minWidth: 140 }}>
            <Field label="Data da coleta">
              {readOnly ? (
                <div style={{ fontSize: 11, color: "#D6D3C7", padding: "9px 0" }}>{fmtDate(form.date)}</div>
              ) : (
                <input type="date" style={inputStyle} value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
              )}
            </Field>
          </div>
          <div style={{ flex: 2, minWidth: 200 }}>
            <Field label="Identificação (opcional)">
              {readOnly ? (
                <div style={{ fontSize: 11, color: "#D6D3C7", padding: "9px 0" }}>{form.label || "—"}</div>
              ) : (
                <input style={inputStyle} value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value })} placeholder="Ex: Análise pré-plantio safra 25/26" />
              )}
            </Field>
          </div>
        </div>
      )}

      {!bounds ? (
        <div style={{ fontSize: 10.5, color: "#E3B455", background: "#332811", borderRadius: 8, padding: 12, marginBottom: 14 }}>
          Esse talhão não tem uma área definida por KML (coordenadas reais) — a amostragem georreferenciada de solo só funciona com um talhão desenhado a partir de KML. Defina a área do talhão nesse formato pra habilitar a coleta.
        </div>
      ) : (
        <>
          {tabsEl}

          {step === "coleta" && !readOnly && (
            <>
              <div style={{ display: "flex", gap: 10, alignItems: "flex-end", marginBottom: 12, flexWrap: "wrap", background: "#10140F", border: "1px solid #212922", borderRadius: 8, padding: 12 }}>
                <div style={{ width: 170 }}>
                  <Field label="Gerar grade a cada (ha)">
                    <input type="number" min="0.1" step="0.5" style={inputStyle} value={gridHectares} onChange={(e) => setGridHectares(e.target.value)} />
                  </Field>
                </div>
                <GhostBtn onClick={handleGenerateGrid} style={{ marginBottom: 14 }}>Gerar grade automática</GhostBtn>
                {gridError && <div style={{ fontSize: 9.5, color: "#E38B84", width: "100%" }}>{gridError}</div>}
              </div>
              <div style={{ fontSize: 9.5, color: "#6B7268", marginBottom: 8 }}>
                Gere a grade automática acima, ou clique direto no mapa pra adicionar/ajustar pontos manualmente. Selecione um ponto na lista abaixo pra preencher o resultado.
              </div>
              <div style={{ display: "flex", gap: 10, alignItems: "center", marginBottom: 12, flexWrap: "wrap", background: "#10140F", border: "1px solid #212922", borderRadius: 8, padding: 12 }}>
                <div style={{ fontSize: 9.5, color: "#9BA298", flex: "1 1 260px" }}>
                  Importar resultados de planilha (XLSX/XLS/CSV) — precisa de uma coluna com o nome do ponto (igual ao rótulo do mapa, ex: "P1") e colunas com os nutrientes.
                </div>
                <input
                  type="file" accept=".xlsx,.xls,.csv"
                  onChange={(e) => { if (e.target.files[0]) handleImportFile(e.target.files[0]); e.target.value = ""; }}
                  style={{ fontSize: 10.5, color: "#D6D3C7" }}
                />
              </div>
              {importSummary && <div style={{ fontSize: 9.5, color: "#7BC142", marginBottom: 10 }}>{importSummary}</div>}
              {importError && <div style={{ fontSize: 9.5, color: "#E38B84", marginBottom: 10 }}>{importError}</div>}

              <div style={{ background: "#10140F", border: "1px solid #212922", borderRadius: 8, padding: 12, marginBottom: 12 }}>
                <div style={{ fontSize: 9.5, color: "#9BA298", marginBottom: 10 }}>
                  Zonas por NDVI (Sentinel-2, via Copernicus) — escolhe um período, busca uma prévia da imagem de satélite (pra conferir se a cultura já está estabelecida e se não tem nuvem cobrindo) e só depois classifica em zonas de vigor.
                </div>
                <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", marginBottom: 10 }}>
                  <span style={{ fontSize: 9.5, color: "#9BA298" }}>De:</span>
                  <input type="date" style={{ ...inputStyle, width: 140 }} value={ndviDateFrom} onChange={(e) => setNdviDateFrom(e.target.value)} />
                  <span style={{ fontSize: 9.5, color: "#9BA298" }}>até:</span>
                  <input type="date" style={{ ...inputStyle, width: 140 }} value={ndviDateTo} onChange={(e) => setNdviDateTo(e.target.value)} />
                  <GhostBtn onClick={handleFetchNdviPreview} disabled={ndviLoading}>{ndviLoading ? "Buscando…" : "Buscar prévia NDVI"}</GhostBtn>
                  {ndviGrid && (
                    <label style={{ display: "flex", alignItems: "center", gap: 6, fontSize: 9.5, color: "#D6D3C7", cursor: "pointer" }}>
                      <input type="checkbox" checked={ndviShowLayer} onChange={(e) => setNdviShowLayer(e.target.checked)} /> Mostrar no mapa
                    </label>
                  )}
                </div>
                {ndviError && <div style={{ fontSize: 9.5, color: "#E38B84", marginBottom: 10 }}>{ndviError}</div>}
                {ndviDateRangeUsed && (
                  <div style={{ fontSize: 9.5, color: "#6B7268", marginBottom: 10 }}>
                    Imagem buscada entre {fmtDate(ndviDateRangeUsed.from)} e {fmtDate(ndviDateRangeUsed.to)} (menos nuvem disponível no período) — confira no mapa se a lavoura já estava instalada e se não tem nuvem cobrindo antes de classificar.
                  </div>
                )}
                {ndviGrid && !ndviZones && (
                  <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", marginBottom: 10 }}>
                    <span style={{ fontSize: 9.5, color: "#9BA298" }}>Hectares por zona de manejo:</span>
                    <input
                      type="number" min="1" step="1" style={{ ...inputStyle, width: 70 }}
                      value={ndviHectaresPerZone} onChange={(e) => setNdviHectaresPerZone(e.target.value)}
                    />
                    <PrimaryBtn onClick={handleClassifyNdvi}>Classificar em zonas</PrimaryBtn>
                  </div>
                )}
                {ndviZones && (
                  <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", marginBottom: 10 }}>
                    <span style={{ fontSize: 9.5, color: "#9BA298" }}>Hectares por zona de manejo:</span>
                    <input
                      type="number" min="1" step="1" style={{ ...inputStyle, width: 70 }}
                      value={ndviHectaresPerZone} onChange={(e) => handleReclassifyNdvi(e.target.value)}
                    />
                    <span style={{ fontSize: 9.5, color: "#9BA298" }}>Pontos/zona:</span>
                    <input
                      type="number" min="1" max="10" step="1" style={{ ...inputStyle, width: 60 }}
                      value={ndviPointsPerZone} onChange={(e) => setNdviPointsPerZone(e.target.value)}
                    />
                  </div>
                )}
                {ndviZones && ndviZones.zones.length > 0 && (
                  <>
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap", marginBottom: 10 }}>
                      {ndviZones.zones.map((z) => {
                        const t = ndviZones.zones.length > 1 ? z.classIndex / (ndviZones.zones.length - 1) : 0.5;
                        const [r, g, b] = ndviColor(t);
                        return (
                          <div key={z.classIndex} style={{ display: "flex", alignItems: "center", gap: 5, fontSize: 9, color: "#9BA298" }}>
                            <span style={{ width: 9, height: 9, borderRadius: 2, background: `rgb(${r},${g},${b})`, display: "inline-block" }} />
                            Zona {z.classIndex + 1} · NDVI {z.ndviAvg.toFixed(2)} · {z.areaHa.toLocaleString("pt-BR", { maximumFractionDigits: 1 })} ha
                          </div>
                        );
                      })}
                    </div>
                    <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                      <GhostBtn onClick={handleGenerateGridFromNdvi}>Gerar grade pelas zonas NDVI</GhostBtn>
                      <GhostBtn onClick={handleExportNdviZones}>Exportar zonas (SHP)</GhostBtn>
                    </div>
                  </>
                )}
              </div>
            </>
          )}

          {step !== "coleta" && (
            <div style={{ marginBottom: 12 }}>{stepControlsEl}</div>
          )}

          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 8, flexWrap: "wrap", gap: 10 }}>
            <div>{opacitySliderEl}</div>
            <GhostBtn onClick={() => setFullscreen(true)}>Tela cheia</GhostBtn>
          </div>
          <div style={{ height: "min(68vh, 620px)", borderRadius: 8, overflow: "hidden", border: "1px solid #232B25", marginBottom: 14, position: "relative" }}>
            {mapEl}
            {legendEl}
            {statsEl}
          </div>

          {step === "coleta" && coletaControlsEl}
        </>
      )}
    </>
  );

  if (onBack) {
    return (
      <div>
        <button onClick={onBack} style={{ background: "none", border: "none", color: "#9BA298", cursor: "pointer", display: "flex", alignItems: "center", gap: 5, fontSize: 10.5, marginBottom: 14, padding: 0 }}>
          <ArrowLeft size={14} /> Voltar
        </button>
        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 18, flexWrap: "wrap", gap: 12 }}>
          <div>
            <h2 style={{ fontFamily: "'Manrope', sans-serif", fontSize: 17.5, fontWeight: 800, color: "#F2F0E6", margin: "0 0 6px" }}>
              {data?.id ? "Editar análise de solo" : "Nova análise de solo"}
            </h2>
            <div style={{ fontSize: 10.5, color: "#9BA298" }}>
              {field.clientName} · {field.propertyName} · {field.name}
            </div>
          </div>
          <div style={{ display: "flex", gap: 12, alignItems: "flex-end", flexWrap: "wrap" }}>
            <div style={{ minWidth: 140 }}>
              <Field label="Data da coleta">
                <input type="date" style={inputStyle} value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} />
              </Field>
            </div>
            <div style={{ minWidth: 200 }}>
              <Field label="Identificação (opcional)">
                <input style={inputStyle} value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value })} placeholder="Ex: Análise pré-plantio safra 25/26" />
              </Field>
            </div>
            <div style={{ display: "flex", gap: 8, marginBottom: 14 }}>
              {form.points.length > 0 && (
                <GhostBtn onClick={() => downloadSoilAnalysisPdf(field, form, Number(desiredV) || 70, npkPdfData)}>Baixar PDF</GhostBtn>
              )}
              <GhostBtn onClick={onBack}>Cancelar</GhostBtn>
              <PrimaryBtn onClick={() => canSave && onSave(form)} disabled={!canSave}>Salvar</PrimaryBtn>
            </div>
          </div>
        </div>
        {bodyEl}
      </div>
    );
  }

  return (
    <Modal title={readOnly ? "Análise de solo" : data?.id ? "Editar análise de solo" : "Nova análise de solo"} onClose={onClose} maxWidth="min(1400px, 95vw)">
      {bodyEl}
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 8 }}>
        {form.points.length > 0 && (
          <GhostBtn onClick={() => downloadSoilAnalysisPdf(field, form, Number(desiredV) || 70, npkPdfData)}>Baixar PDF</GhostBtn>
        )}
        <GhostBtn onClick={onClose}>{readOnly ? "Fechar" : "Cancelar"}</GhostBtn>
        {!readOnly && (
          <PrimaryBtn onClick={() => canSave && onSave(form)} disabled={!canSave}>Salvar</PrimaryBtn>
        )}
      </div>
    </Modal>
  );
}

function FieldDetail({ field, soilAnalyses, onBack, onAddHarvest, onEditHarvest, onDeleteHarvest, onOpenHarvest, onAddSoilAnalysis, onEditSoilAnalysis, onDeleteSoilAnalysis }) {
  if (!field) return null;
  const sorted = [...field.harvests].sort((a, b) => {
    if (a.status !== b.status) return a.status === "Em andamento" ? -1 : 1;
    return (b.plantingDate || "").localeCompare(a.plantingDate || "");
  });
  return (
    <div>
      <button onClick={onBack} style={{ background: "none", border: "none", color: "#9BA298", cursor: "pointer", display: "flex", alignItems: "center", gap: 5, fontSize: 10.5, marginBottom: 14, padding: 0 }}>
        <ArrowLeft size={14} /> Voltar
      </button>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 22 }}>
        <div>
          <h2 style={{ fontFamily: "'Manrope', sans-serif", fontSize: 17.5, fontWeight: 800, color: "#F2F0E6", margin: "0 0 6px", display: "flex", alignItems: "center", gap: 7 }}>
            {field.name}
            {field.fieldMap && <MapPin size={14} color="#7BC142" />}
          </h2>
          <div style={{ display: "flex", gap: 16, fontSize: 10.5, color: "#9BA298" }}>
            <span>{field.clientName} · {field.propertyName}</span>
            <span>{fieldAreaHa(field).toLocaleString("pt-BR")} ha</span>
          </div>
        </div>
        <PrimaryBtn onClick={onAddHarvest}><Plus size={16} /> Nova safra</PrimaryBtn>
      </div>

      {sorted.length === 0 ? (
        <EmptyState icon={Wheat} title="Nenhuma safra cadastrada" sub="Registre o primeiro plantio (soja ou milho) deste talhão." />
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(240px, 1fr))", gap: 12 }}>
          {sorted.map((h) => (
            <div key={h.id} onClick={() => onOpenHarvest(h.id)} style={{
              background: "#161D19", border: "1px solid " + (h.status === "Em andamento" ? "#3E7A3F" : "#232B25"),
              borderRadius: 12, padding: 16, cursor: "pointer"
            }}>
              <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: 8 }}>
                <div style={{ fontWeight: 600, color: "#F2F0E6", fontSize: 12.5 }}>{h.name}</div>
                <CultureBadge culture={h.culture} />
              </div>
              <div style={{ fontSize: 10, color: "#9BA298", marginBottom: 8 }}>
                {h.variety || "cultivar não informado"}
              </div>
              <div style={{ fontSize: 9.5, color: h.status === "Em andamento" ? "#7BC142" : "#9BA298", fontWeight: 600, marginBottom: 8 }}>
                {h.status}
              </div>
              <div style={{ fontSize: 9.5, color: "#6B7268", lineHeight: 1.6 }}>
                <div>Plantio: {fmtDate(h.plantingDate)}</div>
                {h.status === "Em andamento" && h.estimatedHarvestDate && <div>Colheita estimada: {fmtDate(h.estimatedHarvestDate)}</div>}
                {h.harvestDate && <div>Colhida em: {fmtDate(h.harvestDate)}</div>}
              </div>
              {h.lastVisit && (
                <div style={{ marginTop: 10 }}>
                  <StageProgress culture={h.culture} stage={h.lastVisit.stage} />
                </div>
              )}
              <div style={{ display: "flex", gap: 6, marginTop: 12 }} onClick={(e) => e.stopPropagation()}>
                <button onClick={() => onEditHarvest(h)} style={{ ...iconBtnStyle, flex: 1, display: "flex", justifyContent: "center" }}><Pencil size={13} /></button>
                <button onClick={() => { if (confirm(`Remover a safra ${h.name}?`)) onDeleteHarvest(h.id); }} style={{ ...iconBtnStyle, flex: 1, display: "flex", justifyContent: "center" }}><Trash2 size={13} /></button>
              </div>
            </div>
          ))}
        </div>
      )}

      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: 30, marginBottom: 14 }}>
        <h3 style={{ fontFamily: "'Manrope', sans-serif", fontSize: 14, fontWeight: 700, color: "#F2F0E6", margin: 0 }}>Análises de Solo</h3>
        {field.fieldMap?.mode === "kml" && field.fieldMap.points?.length >= 3 && (
          <PrimaryBtn onClick={onAddSoilAnalysis}><Plus size={16} /> Nova análise de solo</PrimaryBtn>
        )}
      </div>
      {field.fieldMap?.mode !== "kml" || !(field.fieldMap.points?.length >= 3) ? (
        <div style={{ fontSize: 10.5, color: "#9BA298", background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: 16 }}>
          Amostragem georreferenciada de solo só funciona com um talhão desenhado a partir de KML (coordenadas reais). Defina a área desse talhão nesse formato pra habilitar.
        </div>
      ) : soilAnalyses.length === 0 ? (
        <EmptyState icon={FlaskConical} title="Nenhuma análise de solo registrada" sub="Registre a primeira coleta georreferenciada deste talhão." />
      ) : (
        <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 12 }}>
          {[...soilAnalyses].sort((a, b) => (b.date || "").localeCompare(a.date || "")).map((s) => (
            <div key={s.id} onClick={() => onEditSoilAnalysis(s)} style={{
              background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: 16, cursor: "pointer"
            }}>
              <div style={{ display: "flex", alignItems: "center", gap: 7, marginBottom: 6 }}>
                <FlaskConical size={14} color="#7BC142" />
                <div style={{ fontWeight: 600, color: "#F2F0E6", fontSize: 11.5 }}>{s.label || fmtDate(s.date)}</div>
              </div>
              <div style={{ fontSize: 9.5, color: "#9BA298", marginBottom: 10 }}>
                {fmtDate(s.date)} · {s.points.length} ponto(s) coletado(s)
              </div>
              <div style={{ display: "flex", gap: 6 }} onClick={(e) => e.stopPropagation()}>
                <button onClick={() => onEditSoilAnalysis(s)} style={{ ...iconBtnStyle, flex: 1, display: "flex", justifyContent: "center" }}><Pencil size={13} /></button>
                <button onClick={() => { if (confirm(`Remover a análise "${s.label || fmtDate(s.date)}"?`)) onDeleteSoilAnalysis(s.id); }} style={{ ...iconBtnStyle, flex: 1, display: "flex", justifyContent: "center" }}><Trash2 size={13} /></button>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

