function CatalogTable({ icon, items, columns, emptyTitle, emptySub, addLabel, onAdd, onEdit, onDelete }) {
  return (
    <div>
      <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 14 }}>
        <PrimaryBtn onClick={onAdd}><Plus size={16} /> {addLabel}</PrimaryBtn>
      </div>
      {items.length === 0 ? (
        <EmptyState icon={icon} title={emptyTitle} sub={emptySub} action={<PrimaryBtn onClick={onAdd}><Plus size={16} /> {addLabel}</PrimaryBtn>} />
      ) : (
        <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, overflow: "hidden" }}>
          <table>
            <thead>
              <tr>
                {columns.map((col) => <th key={col.key}>{col.label}</th>)}
                <th></th>
              </tr>
            </thead>
            <tbody>
              {items.map((item) => (
                <tr key={item.id}>
                  {columns.map((col, i) => (
                    <td key={col.key} style={i === 0 ? { fontWeight: 600, color: "#F2F0E6" } : undefined}>
                      {col.render ? col.render(item) : (item[col.key] || "—")}
                    </td>
                  ))}
                  <td>
                    <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
                      <button onClick={() => onEdit(item)} style={iconBtnStyle}><Pencil size={14} /></button>
                      <button onClick={() => onDelete(item)} style={iconBtnStyle}><Trash2 size={14} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function ExpenseCategoryModal({ data, onSave, onClose }) {
  const [form, setForm] = useState({ name: "", ...(data || {}) });
  return (
    <Modal title={data?.id ? "Editar categoria" : "Nova categoria de despesa"} onClose={onClose}>
      <Field label="Nome da categoria">
        <input style={inputStyle} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Ex: Combustível" />
      </Field>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 8 }}>
        <GhostBtn onClick={onClose}>Cancelar</GhostBtn>
        <PrimaryBtn onClick={() => form.name.trim() && onSave(form)}>Salvar</PrimaryBtn>
      </div>
    </Modal>
  );
}

function AjudaCustoModal({ data, onSave, onClose }) {
  const [form, setForm] = useState({ estado: "", municipio: "", valor: "", distanciaKm: "", ...(data || {}) });
  const municipios = form.estado ? (MUNICIPIOS_POR_UF[form.estado] || []) : [];
  return (
    <Modal title={data?.id ? "Editar ajuda de custo" : "Nova ajuda de custo"} onClose={onClose}>
      <Field label="Estado">
        <select style={inputStyle} value={form.estado} onChange={(e) => setForm({ ...form, estado: e.target.value, municipio: "" })}>
          <option value="">Selecione…</option>
          {ESTADOS.map((e) => <option key={e.sigla} value={e.sigla}>{e.nome} ({e.sigla})</option>)}
        </select>
      </Field>
      <Field label="Município">
        <select style={inputStyle} value={form.municipio} onChange={(e) => setForm({ ...form, municipio: e.target.value })} disabled={!form.estado}>
          <option value="">{form.estado ? "Selecione…" : "Selecione o estado primeiro"}</option>
          {municipios.map((m) => <option key={m} value={m}>{m}</option>)}
        </select>
      </Field>
      <Field label="Valor por hectare atendido (R$/ha/ano)">
        <input type="number" style={inputStyle} value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} placeholder="Ex: 2,50" />
      </Field>
      <Field label="Distância aproximada (km) — opcional">
        <input type="number" style={inputStyle} value={form.distanciaKm} onChange={(e) => setForm({ ...form, distanciaKm: e.target.value })} placeholder="Ex: 180" />
      </Field>
      <div style={{ fontSize: 10, color: "#6B7268", marginTop: -8, marginBottom: 8 }}>
        É um valor por ano, igual ao Pró-labore por hectare — o cálculo mensal usa este valor ÷ 12. Some automaticamente ao Pró-labore do gestor responsável pelo cliente dono da fazenda (coluna "Ajuda de custo" em Financeiro › Pró-labore).
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 8 }}>
        <GhostBtn onClick={onClose}>Cancelar</GhostBtn>
        <PrimaryBtn onClick={() => form.estado && form.municipio && form.valor && onSave(form)}>Salvar</PrimaryBtn>
      </div>
    </Modal>
  );
}

