const SERVICE_COBRANCA_LABELS = { area: "Por área", valor: "% do valor", unidade: "Por unidade" };

function serviceCobrancaSummary(type) {
  if (!type) return "—";
  if (type.cobranca === "area") return `R$ ${Number(type.valorPorHa || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2 })}/ha/ano`;
  if (type.cobranca === "valor") return `${Number(type.percentual || 0).toLocaleString("pt-BR")}% do valor do projeto`;
  if (type.cobranca === "unidade") return `R$ ${Number(type.valorPorUnidade || 0).toLocaleString("pt-BR", { minimumFractionDigits: 2 })} por ${type.unidadeLabel || "unidade"}`;
  return "—";
}

function ServicosView({ services, clients, serviceTypes, team, onAdd, onEdit, onDelete, hasClients }) {
  const rows = useMemo(() => {
    return [...services]
      .map((s) => ({
        ...s,
        clientName: clients.find((c) => c.id === s.clientId)?.name || "—",
        gestorName: team.find((t) => t.id === s.gestorId)?.name || "—",
      }))
      .sort((a, b) => (b.vencimento || "").localeCompare(a.vencimento || ""));
  }, [services, clients, team]);

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18, gap: 12 }}>
        <h2 style={{ fontFamily: "'Manrope', sans-serif", fontSize: 17.5, fontWeight: 800, color: "#F2F0E6", margin: 0 }}>Serviços</h2>
        <PrimaryBtn onClick={onAdd} disabled={!hasClients} style={!hasClients ? { opacity: 0.5, cursor: "not-allowed" } : {}}>
          <Plus size={16} /> Novo serviço
        </PrimaryBtn>
      </div>
      {!hasClients && (
        <div style={{ display: "flex", gap: 8, alignItems: "center", background: "#332811", color: "#E3B455", padding: "10px 14px", borderRadius: 8, fontSize: 10.5, marginBottom: 16 }}>
          <AlertTriangle size={15} /> Cadastre um cliente antes de adicionar um serviço.
        </div>
      )}
      {rows.length === 0 ? (
        <EmptyState icon={Briefcase} title="Nenhum serviço cadastrado" sub="Cadastre os serviços contratados por cada cliente para acompanhar o andamento e o recebimento." />
      ) : (
        <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, overflow: "hidden" }}>
          <table>
            <thead>
              <tr>
                <th>Código</th><th>Cliente</th><th>Tipo</th><th>Gestor</th><th>Valor</th><th>Competência</th><th>Vencimento</th><th>Periodicidade</th><th>Status</th><th></th>
              </tr>
            </thead>
            <tbody>
              {rows.map((s) => (
                <tr key={s.id}>
                  <td style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 10, color: "#9BC98A" }}>{s.codigo || "—"}</td>
                  <td style={{ fontWeight: 600, color: "#F2F0E6" }}>{s.clientName}</td>
                  <td>{s.tipo || "—"}</td>
                  <td>{s.gestorName}</td>
                  <td>{fmtCurrency(Number(s.valor || 0))}</td>
                  <td>{s.competencia || "—"}</td>
                  <td>{fmtDate(s.vencimento)}</td>
                  <td>
                    {SERVICE_PERIODICIDADE_LABELS[s.periodicidade] || "—"}
                    {s.periodicidade !== "unica" && s.recorrente ? " · recorrente" : ""}
                  </td>
                  <td><ServiceStatusBadge status={s.status} /></td>
                  <td>
                    <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
                      <button onClick={() => onEdit(s)} style={iconBtnStyle}><Pencil size={14} /></button>
                      <button onClick={() => { if (confirm(`Remover o serviço ${s.codigo || ""} de ${s.clientName}?`)) onDelete(s.id); }} style={iconBtnStyle}><Trash2 size={14} /></button>
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function nextServiceCode(services) {
  const year = new Date().getFullYear();
  const prefix = `CS-${year}-`;
  const maxN = (services || [])
    .map((s) => s.codigo)
    .filter((c) => c && c.startsWith(prefix))
    .map((c) => parseInt(c.slice(prefix.length), 10))
    .filter((n) => !Number.isNaN(n))
    .reduce((max, n) => Math.max(max, n), 0);
  return `${prefix}${String(maxN + 1).padStart(3, "0")}`;
}

function ServiceModal({ data, clients, team, serviceTypes, services, onSave, onClose }) {
  const [form, setForm] = useState({
    codigo: data?.codigo || nextServiceCode(services),
    tipo: "", clientId: clients[0]?.id || "", gestorId: "", valor: "",
    areaHa: "", valorProjeto: "", quantidade: "1",
    competencia: new Date().toISOString().slice(0, 7),
    periodicidade: "unica", recorrente: false, vencimento: new Date().toISOString().slice(0, 10), status: "negociacao",
    ...(data || {}),
  });
  const tipoOptions = Array.from(new Set([...(serviceTypes || []).map((t) => t.name), ...DEFAULT_SERVICE_TYPES]));
  const selectedType = (serviceTypes || []).find((t) => t.name === form.tipo);

  function applyTipo(tipoName) {
    const type = (serviceTypes || []).find((t) => t.name === tipoName);
    setForm((f) => {
      const next = { ...f, tipo: tipoName };
      if (type?.cobranca === "area") next.periodicidade = f.periodicidade === "unica" ? "anual" : f.periodicidade;
      return next;
    });
  }

  function applyCalc(patch) {
    setForm((f) => {
      const next = { ...f, ...patch };
      if (!selectedType) return next;
      if (selectedType.cobranca === "area") next.valor = String((Number(next.areaHa) || 0) * (Number(selectedType.valorPorHa) || 0));
      if (selectedType.cobranca === "valor") next.valor = String(((Number(next.valorProjeto) || 0) * (Number(selectedType.percentual) || 0)) / 100);
      if (selectedType.cobranca === "unidade") next.valor = String((Number(next.quantidade) || 0) * (Number(selectedType.valorPorUnidade) || 0));
      return next;
    });
  }

  const canSave = form.codigo.trim() && form.tipo.trim() && form.clientId && form.gestorId && Number(form.valor) > 0 && form.vencimento;
  return (
    <Modal title={data?.id ? "Editar serviço" : "Novo serviço"} onClose={onClose}>
      <Field label="Código do serviço">
        <input style={inputStyle} value={form.codigo} onChange={(e) => setForm({ ...form, codigo: e.target.value })} placeholder="Ex: CS-2026-001" />
      </Field>
      <Field label="Tipo de serviço">
        <input style={inputStyle} list="service-types" value={form.tipo} onChange={(e) => applyTipo(e.target.value)} placeholder="Ex: Assistência Técnica" />
        <datalist id="service-types">
          {tipoOptions.map((t) => <option key={t} value={t} />)}
        </datalist>
        <div style={{ fontSize: 9.5, color: "#6B7268", marginTop: 4 }}>
          {selectedType ? `Cobrança: ${serviceCobrancaSummary(selectedType)}` : "Gerencie a lista de tipos em Configurações."}
        </div>
      </Field>
      <Field label="Contratante / Cliente">
        {clients.length === 0 ? (
          <div style={{ fontSize: 10.5, color: "#6B7268", padding: "8px 0" }}>Nenhum cliente cadastrado ainda. Cadastre em Clientes.</div>
        ) : (
          <select style={inputStyle} value={form.clientId} onChange={(e) => setForm({ ...form, clientId: e.target.value })}>
            <option value="">Selecione…</option>
            {clients.map((c) => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
        )}
      </Field>
      <Field label="Gestor responsável">
        {team.length === 0 ? (
          <div style={{ fontSize: 10.5, color: "#6B7268", padding: "8px 0" }}>Nenhum colaborador cadastrado ainda. Cadastre em Configurações › Equipe.</div>
        ) : (
          <select style={inputStyle} value={form.gestorId} onChange={(e) => setForm({ ...form, gestorId: e.target.value })}>
            <option value="">Selecione…</option>
            {team.map((t) => <option key={t.id} value={t.id}>{t.name}</option>)}
          </select>
        )}
        <div style={{ fontSize: 9.5, color: "#6B7268", marginTop: 4 }}>É quem ganha a participação sobre este serviço quando ele for recebido.</div>
      </Field>

      {selectedType?.cobranca === "area" && (
        <Field label="Área atendida (ha)">
          <input type="number" style={inputStyle} value={form.areaHa} onChange={(e) => applyCalc({ areaHa: e.target.value })} placeholder="Ex: 500" />
        </Field>
      )}
      {selectedType?.cobranca === "valor" && (
        <Field label="Valor do projeto (R$)">
          <input type="number" style={inputStyle} value={form.valorProjeto} onChange={(e) => applyCalc({ valorProjeto: e.target.value })} placeholder="Ex: 200000" />
        </Field>
      )}
      {selectedType?.cobranca === "unidade" && (
        <Field label={`Quantidade${selectedType.unidadeLabel ? ` (${selectedType.unidadeLabel})` : ""}`}>
          <input type="number" style={inputStyle} value={form.quantidade} onChange={(e) => applyCalc({ quantidade: e.target.value })} placeholder="Ex: 1" />
        </Field>
      )}

      <Field label="Valor (R$)">
        <input type="number" style={inputStyle} value={form.valor} onChange={(e) => setForm({ ...form, valor: e.target.value })} placeholder="Ex: 3500" />
        {selectedType && <div style={{ fontSize: 9.5, color: "#6B7268", marginTop: 4 }}>Calculado a partir da forma de cobrança do tipo — pode ajustar se precisar.</div>}
      </Field>
      <Field label="Competência (mês de referência)">
        <input type="month" style={inputStyle} value={form.competencia} onChange={(e) => setForm({ ...form, competencia: e.target.value })} />
      </Field>
      <Field label="Periodicidade">
        <select style={inputStyle} value={form.periodicidade} onChange={(e) => setForm({ ...form, periodicidade: e.target.value, recorrente: e.target.value === "unica" ? false : form.recorrente })}>
          <option value="unica">Única</option>
          <option value="mensal">Mensal</option>
          <option value="anual">Anual</option>
        </select>
      </Field>
      {form.periodicidade !== "unica" && (
        <Field label="Recorrente?">
          <label style={{ display: "flex", alignItems: "center", gap: 8, fontSize: 11, color: "#D6D3C7" }}>
            <input type="checkbox" checked={!!form.recorrente} onChange={(e) => setForm({ ...form, recorrente: e.target.checked })} />
            Lançar automaticamente os próximos períodos
          </label>
        </Field>
      )}
      <Field label="Vencimento">
        <input type="date" style={inputStyle} value={form.vencimento} onChange={(e) => setForm({ ...form, vencimento: e.target.value })} />
      </Field>
      <Field label="Status">
        <select style={inputStyle} value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })}>
          {SERVICE_STATUS.map((s) => <option key={s.key} value={s.key}>{s.label}</option>)}
        </select>
      </Field>
      <div style={{ fontSize: 10, color: "#6B7268", marginTop: -8, marginBottom: 8 }}>
Ao marcar como "Finalizado", gera um honorário Pendente em Financeiro (aparece em Entradas Previstas e no Extrato, com data do vencimento). Ao marcar como "Recebido", esse honorário vira Pago e conta como pró-labore pro gestor responsável escolhido acima. Voltar pra "Em negociação"/"Em andamento" ou editar o serviço atualiza/remove o honorário automaticamente.
      </div>
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 8 }}>
        <GhostBtn onClick={onClose}>Cancelar</GhostBtn>
        <PrimaryBtn onClick={() => canSave && onSave(form)} disabled={!canSave} style={!canSave ? { opacity: 0.5, cursor: "not-allowed" } : {}}>Salvar</PrimaryBtn>
      </div>
    </Modal>
  );
}

function ServiceTypeModal({ data, onSave, onClose }) {
  const [form, setForm] = useState({ name: "", cobranca: "area", valorPorHa: "", percentual: "", valorPorUnidade: "", unidadeLabel: "", ...(data || {}) });
  const canSave = form.name.trim() && (
    (form.cobranca === "area" && Number(form.valorPorHa) > 0) ||
    (form.cobranca === "valor" && Number(form.percentual) > 0) ||
    (form.cobranca === "unidade" && Number(form.valorPorUnidade) > 0 && form.unidadeLabel.trim())
  );
  return (
    <Modal title={data?.id ? "Editar tipo" : "Novo tipo de serviço"} onClose={onClose}>
      <Field label="Nome do tipo">
        <input style={inputStyle} value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} placeholder="Ex: Assistência Técnica" />
      </Field>
      <Field label="Forma de cobrança">
        <select style={inputStyle} value={form.cobranca} onChange={(e) => setForm({ ...form, cobranca: e.target.value })}>
          <option value="area">Por área (R$/hectare/ano)</option>
          <option value="valor">% do valor (percentual sobre o valor do projeto)</option>
          <option value="unidade">Por unidade (R$ por unidade)</option>
        </select>
      </Field>
      {form.cobranca === "area" && (
        <Field label="Valor por hectare/ano (R$)">
          <input type="number" style={inputStyle} value={form.valorPorHa} onChange={(e) => setForm({ ...form, valorPorHa: e.target.value })} placeholder="Ex: 60" />
        </Field>
      )}
      {form.cobranca === "valor" && (
        <Field label="Percentual sobre o valor do projeto (%)">
          <input type="number" style={inputStyle} value={form.percentual} onChange={(e) => setForm({ ...form, percentual: e.target.value })} placeholder="Ex: 0,5" />
        </Field>
      )}
      {form.cobranca === "unidade" && (
        <>
          <Field label="Valor por unidade (R$)">
            <input type="number" style={inputStyle} value={form.valorPorUnidade} onChange={(e) => setForm({ ...form, valorPorUnidade: e.target.value })} placeholder="Ex: 200" />
          </Field>
          <Field label="Nome da unidade">
            <input style={inputStyle} value={form.unidadeLabel} onChange={(e) => setForm({ ...form, unidadeLabel: e.target.value })} placeholder="Ex: limite de crédito bancário" />
          </Field>
        </>
      )}
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 8 }}>
        <GhostBtn onClick={onClose}>Cancelar</GhostBtn>
        <PrimaryBtn onClick={() => canSave && onSave(form)} disabled={!canSave} style={!canSave ? { opacity: 0.5, cursor: "not-allowed" } : {}}>Salvar</PrimaryBtn>
      </div>
    </Modal>
  );
}

function FinanceiroView({
  finances, bonuses, bills, settings, clients, team, properties, fields, ajudaCusto,
  onAddFinance, onEditFinance, onDeleteFinance,
  onAddBonus, onEditBonus, onDeleteBonus,
  onAddBill, onEditBill, onDeleteBill,
  onChangeRate, onChangeProjectRate, onReconcile, onGenerateProLaboreBills,
}) {
  const [tab, setTab] = useState("painel");
  const [month, setMonth] = useState(() => new Date().toISOString().slice(0, 7));
  const [rateInput, setRateInput] = useState(String(settings.commissionRatePerHaYear ?? 30));
  const [projectRateInput, setProjectRateInput] = useState(String(settings.projectShareRate ?? 20));
  const [extratoPeriodo, setExtratoPeriodo] = useState("mensal");
  const [extratoDia, setExtratoDia] = useState(() => new Date().toISOString().slice(0, 10));
  const [extratoMes, setExtratoMes] = useState(() => new Date().toISOString().slice(0, 7));
  const [extratoAno, setExtratoAno] = useState(() => new Date().toISOString().slice(0, 4));
  const [fluxoPeriodo, setFluxoPeriodo] = useState("mensal");

  const summary = useMemo(
    () => computeMonthFinanceSummary({ finances, bonuses, bills, settings, clients, team, properties, fields, ajudaCusto, month }),
    [finances, bonuses, bills, settings, clients, team, properties, fields, ajudaCusto, month]
  );
  const monthFinances = [...summary.monthFinances].sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const { totalRecebido, totalPendente } = summary;
  const monthBonuses = bonuses.filter((b) => (b.date || "").slice(0, 7) === month).sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const monthBillsSorted = [...summary.monthBills].sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  const { totalDespesasPagas, totalDespesasPendentes } = summary;

  const commissionRows = summary.proLaboreRows
    .filter((r) => r.areaHa > 0 || r.projectShare > 0 || r.bonusTotal > 0 || r.ajudaCustoTotal > 0)
    .sort((a, b) => b.total - a.total);

  const totalComissoes = summary.totalProLabore;

  const proLaboreGeneratedIds = useMemo(
    () => new Set(bills.filter((b) => b.proLaboreMonth === month).map((b) => b.proLaboreGestorId)),
    [bills, month]
  );

  const cashFlowMonths = useMemo(() => {
    if (tab !== "fluxocaixa" || fluxoPeriodo !== "mensal") return [];
    const result = [];
    for (let i = 11; i >= 0; i--) {
      const m = addMonthsToReferenceMonth(month, -i);
      const s = computeMonthFinanceSummary({ finances, bonuses, bills, settings, clients, team, properties, fields, ajudaCusto, month: m });
      const [y, mm] = m.split("-").map(Number);
      const label = new Date(y, mm - 1, 1).toLocaleDateString("pt-BR", { month: "short" }).replace(".", "");
      result.push({ month: m, label, entradas: s.totalEntradasPrevistas, saidas: s.totalSaidasPrevistas });
    }
    return result;
  }, [tab, fluxoPeriodo, finances, bonuses, bills, settings, clients, team, properties, fields, ajudaCusto, month]);

  const cashFlowYears = useMemo(() => {
    if (tab !== "fluxocaixa" || fluxoPeriodo !== "anual") return [];
    const currentYear = Number(month.slice(0, 4));
    const result = [];
    for (let y = currentYear - 4; y <= currentYear; y++) {
      let entradas = 0, saidas = 0;
      for (let mm = 1; mm <= 12; mm++) {
        const m = `${y}-${String(mm).padStart(2, "0")}`;
        const s = computeMonthFinanceSummary({ finances, bonuses, bills, settings, clients, team, properties, fields, ajudaCusto, month: m });
        entradas += s.totalEntradasPrevistas;
        saidas += s.totalSaidasPrevistas;
      }
      result.push({ month: String(y), label: String(y), entradas, saidas });
    }
    return result;
  }, [tab, fluxoPeriodo, finances, bonuses, bills, settings, clients, team, properties, fields, ajudaCusto, month]);

  const extratoRows = useMemo(() => {
    const entradas = finances.map((f) => ({
      id: `f-${f.id}`, kind: "entrada", label: clients.find((c) => c.id === f.clientId)?.name || "Honorário",
      date: f.date, amount: Number(f.amount), status: f.status,
    }));
    const saidas = bills.map((b) => ({
      id: `b-${b.id}`, kind: "saida", label: b.description, date: b.date, amount: Number(b.amount), status: b.status,
    }));
    return [...entradas, ...saidas]
      .filter((m) => {
        if (!m.date) return false;
        if (extratoPeriodo === "diario") return m.date === extratoDia;
        if (extratoPeriodo === "mensal") return m.date.slice(0, 7) === extratoMes;
        return m.date.slice(0, 4) === extratoAno;
      })
      .sort((a, b) => (b.date || "").localeCompare(a.date || ""));
  }, [finances, bills, clients, extratoPeriodo, extratoDia, extratoMes, extratoAno]);

  const extratoTotals = useMemo(() => {
    const entradas = extratoRows.filter((m) => m.kind === "entrada").reduce((s, m) => s + m.amount, 0);
    const saidas = extratoRows.filter((m) => m.kind === "saida").reduce((s, m) => s + m.amount, 0);
    return { entradas, saidas, saldo: entradas - saidas };
  }, [extratoRows]);

  const pendingItems = useMemo(() => {
    const fin = summary.monthFinances.filter((f) => f.status === "pendente").map((f) => ({
      id: `f-${f.id}`, kind: "entrada", amount: Number(f.amount), date: f.date,
      label: clients.find((c) => c.id === f.clientId)?.name || "Honorário",
    }));
    const desp = summary.monthBills.filter((b) => b.status === "pendente").map((b) => ({
      id: `b-${b.id}`, kind: "saida", amount: Number(b.amount), date: b.date,
      label: b.description,
    }));
    return [...fin, ...desp].sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  }, [summary, clients]);

  const reconciledFeed = useMemo(() => {
    const fin = finances.filter((f) => f.reconciledBank).map((f) => ({
      id: `f-${f.id}`, kind: "entrada", amount: Number(f.amount), date: f.date, at: f.reconciledAt || f.date,
      label: clients.find((c) => c.id === f.clientId)?.name || "Honorário",
    }));
    const desp = bills.filter((b) => b.reconciledBank).map((b) => ({
      id: `b-${b.id}`, kind: "saida", amount: Number(b.amount), date: b.date, at: b.reconciledAt || b.date,
      label: b.description,
    }));
    return [...fin, ...desp].sort((a, b) => (b.at || "").localeCompare(a.at || "")).slice(0, 8);
  }, [finances, bills, clients]);

  const saldoPrevisto = summary.totalEntradasPrevistas - summary.totalSaidasPrevistas;

  const FINANCEIRO_TABS = [
    { id: "painel", label: "Painel", icon: LayoutDashboard },
    { id: "extrato", label: "Extrato de Movimentações", icon: FileText },
    { id: "fluxocaixa", label: "Fluxo de Caixa", icon: TrendingUp },
    { id: "honorarios", label: "Honorários", icon: Wallet },
    { id: "comissoes", label: "Pró-labore", icon: UserCog },
    { id: "despesas", label: "Despesas", icon: Receipt },
  ];
  const showMonthPicker = tab === "painel" || tab === "honorarios" || tab === "comissoes" || tab === "despesas";

  return (
    <div>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 18, gap: 12, flexWrap: "wrap" }}>
        <div>
          <h2 style={{ fontFamily: "'Manrope', sans-serif", fontSize: 17.5, fontWeight: 800, color: "#F2F0E6", margin: "0 0 4px" }}>Financeiro</h2>
          <p style={{ color: "#9BA298", fontSize: 10.5, margin: 0 }}>Honorários recebidos e pró-labore da equipe</p>
        </div>
        {showMonthPicker && (
          <input type="month" style={{ ...inputStyle, width: 160 }} value={month} onChange={(e) => setMonth(e.target.value)} />
        )}
      </div>

      <div style={{ display: "flex", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
        {FINANCEIRO_TABS.map((t) => {
          const Icon = t.icon;
          const active = tab === t.id;
          return (
            <button key={t.id} onClick={() => setTab(t.id)} style={{
              display: "flex", alignItems: "center", gap: 7, padding: "8px 16px", borderRadius: 20,
              border: "1px solid " + (active ? "#1E4A20" : "#232B25"),
              background: active ? "#1E4A20" : "#161D19", color: active ? "#F5F2E8" : "#D6D3C7",
              fontSize: 10.5, fontWeight: 600, cursor: "pointer"
            }}>
              <Icon size={15} /> {t.label}
            </button>
          );
        })}
      </div>

      {tab === "painel" && (
        <div>
          <div style={{ display: "flex", gap: 14, marginBottom: 14, flexWrap: "wrap" }}>
            <StatCard label="Entradas previstas no mês" value={fmtCurrency(summary.totalEntradasPrevistas)} accent="#7BC142" />
            <StatCard label="Entradas recebidas no mês" value={fmtCurrency(totalRecebido)} accent="#7BC142" />
            <StatCard label="Saídas previstas no mês" value={fmtCurrency(summary.totalSaidasPrevistas)} accent="#E3B455"
              sub={`Pró-labore ${fmtCurrency(summary.totalProLabore)} + despesas ${fmtCurrency(summary.totalDespesasDoMes)}`} />
            <StatCard label="Saídas realizadas no mês" value={fmtCurrency(totalDespesasPagas + summary.totalProLabore)} accent="#E38B84"
              sub={`Despesas pagas ${fmtCurrency(totalDespesasPagas)} + pró-labore ${fmtCurrency(summary.totalProLabore)}`} />
          </div>

          <div style={{ display: "flex", gap: 14, marginBottom: 20, flexWrap: "wrap" }}>
            <StatCard label="Saldo previsto no mês" value={fmtCurrency(saldoPrevisto)} accent={saldoPrevisto >= 0 ? "#7BC142" : "#E38B84"} />
          </div>

          <div style={{ display: "flex", gap: 18, flexWrap: "wrap", marginBottom: 14 }}>
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: 18, flex: 1, minWidth: 240 }}>
              <div style={{ fontSize: 10.5, fontWeight: 600, color: "#D6D3C7", marginBottom: 12 }}>Pendências do mês</div>
              {pendingItems.length === 0 ? (
                <div style={{ color: "#6B7268", fontSize: 10.5 }}>Nada pendente neste mês.</div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 9, maxHeight: 210, overflowY: "auto" }}>
                  {pendingItems.map((item) => (
                    <div key={item.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, fontSize: 10 }}>
                      <span style={{ color: "#D6D3C7", minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>
                        <strong style={{ color: item.kind === "entrada" ? "#7BC142" : "#E38B84", marginRight: 5 }}>{item.kind === "entrada" ? "↑" : "↓"}</strong>
                        {item.label}
                      </span>
                      <strong style={{ color: "#F2F0E6", whiteSpace: "nowrap" }}>{fmtCurrency(item.amount)}</strong>
                    </div>
                  ))}
                </div>
              )}
            </div>

            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: 18, flex: 1, minWidth: 240 }}>
              <div style={{ fontSize: 10.5, fontWeight: 600, color: "#D6D3C7", marginBottom: 12 }}>Últimas movimentações conciliadas</div>
              {reconciledFeed.length === 0 ? (
                <div style={{ color: "#6B7268", fontSize: 10.5 }}>Nenhuma conciliação bancária registrada ainda.</div>
              ) : (
                <div style={{ display: "flex", flexDirection: "column", gap: 9 }}>
                  {reconciledFeed.map((item) => (
                    <div key={item.id} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: 8, fontSize: 10.5 }}>
                      <span style={{ color: "#D6D3C7" }}>
                        <strong style={{ color: item.kind === "entrada" ? "#7BC142" : "#E38B84", marginRight: 5 }}>{item.kind === "entrada" ? "↑" : "↓"}</strong>
                        {item.label} <span style={{ color: "#6B7268" }}>· {fmtDate(item.date)}</span>
                      </span>
                      <strong style={{ color: "#F2F0E6" }}>{fmtCurrency(item.amount)}</strong>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {tab === "extrato" && (
        <div>
          <div style={{ display: "flex", gap: 8, marginBottom: 16, flexWrap: "wrap", alignItems: "center" }}>
            <div style={{ display: "flex", gap: 8 }}>
              {[["diario", "Diário"], ["mensal", "Mensal"], ["anual", "Anual"]].map(([key, label]) => (
                <button key={key} onClick={() => setExtratoPeriodo(key)} style={{
                  padding: "7px 14px", borderRadius: 20, fontSize: 10, fontWeight: 600, cursor: "pointer",
                  border: "1px solid " + (extratoPeriodo === key ? "#1E4A20" : "#232B25"),
                  background: extratoPeriodo === key ? "#1E4A20" : "#161D19", color: extratoPeriodo === key ? "#F5F2E8" : "#D6D3C7",
                }}>{label}</button>
              ))}
            </div>
            {extratoPeriodo === "diario" && (
              <input type="date" style={{ ...inputStyle, width: 160 }} value={extratoDia} onChange={(e) => setExtratoDia(e.target.value)} />
            )}
            {extratoPeriodo === "mensal" && (
              <input type="month" style={{ ...inputStyle, width: 160 }} value={extratoMes} onChange={(e) => setExtratoMes(e.target.value)} />
            )}
            {extratoPeriodo === "anual" && (
              <input type="number" style={{ ...inputStyle, width: 100 }} value={extratoAno} onChange={(e) => setExtratoAno(e.target.value)} />
            )}
          </div>

          <div style={{ display: "flex", gap: 14, marginBottom: 20, flexWrap: "wrap" }}>
            <StatCard label="Entradas no período" value={fmtCurrency(extratoTotals.entradas)} accent="#7BC142" />
            <StatCard label="Saídas no período" value={fmtCurrency(extratoTotals.saidas)} accent="#E38B84" />
            <StatCard label="Saldo do período" value={fmtCurrency(extratoTotals.saldo)} accent={extratoTotals.saldo >= 0 ? "#7BC142" : "#E38B84"} />
          </div>

          {extratoRows.length === 0 ? (
            <EmptyState icon={FileText} title="Nenhuma movimentação neste período" sub="Ajuste o período acima ou registre honorários e despesas." />
          ) : (
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, overflow: "hidden" }}>
              <table>
                <thead><tr><th>Data</th><th>Descrição</th><th>Tipo</th><th>Status</th><th>Valor</th></tr></thead>
                <tbody>
                  {extratoRows.map((m) => (
                    <tr key={m.id}>
                      <td style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 10 }}>{fmtDate(m.date)}</td>
                      <td style={{ fontWeight: 600, color: "#F2F0E6" }}>{m.label}</td>
                      <td>
                        <span style={{ color: m.kind === "entrada" ? "#7BC142" : "#E38B84", fontWeight: 600 }}>
                          {m.kind === "entrada" ? "↑ Entrada" : "↓ Saída"}
                        </span>
                      </td>
                      <td><FinanceStatusBadge status={m.status} /></td>
                      <td>{fmtCurrency(m.amount)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {tab === "fluxocaixa" && (
        <div>
          <div style={{ display: "flex", gap: 8, marginBottom: 16 }}>
            {[["mensal", "Mensal"], ["anual", "Anual"]].map(([key, label]) => (
              <button key={key} onClick={() => setFluxoPeriodo(key)} style={{
                padding: "7px 14px", borderRadius: 20, fontSize: 10, fontWeight: 600, cursor: "pointer",
                border: "1px solid " + (fluxoPeriodo === key ? "#1E4A20" : "#232B25"),
                background: fluxoPeriodo === key ? "#1E4A20" : "#161D19", color: fluxoPeriodo === key ? "#F5F2E8" : "#D6D3C7",
              }}>{label}</button>
            ))}
          </div>
          <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: 18 }}>
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12, flexWrap: "wrap", gap: 8 }}>
              <div style={{ fontSize: 10.5, fontWeight: 600, color: "#D6D3C7" }}>
                {fluxoPeriodo === "mensal" ? "Fluxo de caixa · últimos 12 meses" : "Fluxo de caixa · últimos 5 anos"}
              </div>
              <div style={{ display: "flex", gap: 12, fontSize: 9.5, color: "#9BA298" }}>
                <span style={{ display: "flex", alignItems: "center", gap: 5 }}>
                  <span style={{ width: 8, height: 8, borderRadius: 2, background: "#7BC142", display: "inline-block" }} />Entradas
                </span>
                <span style={{ display: "flex", alignItems: "center", gap: 5 }}>
                  <span style={{ width: 8, height: 8, borderRadius: 2, background: "#E38B84", display: "inline-block" }} />Saídas
                </span>
              </div>
            </div>
            <CashFlowChart months={fluxoPeriodo === "mensal" ? cashFlowMonths : cashFlowYears} />
          </div>
        </div>
      )}

      {tab === "honorarios" && (
        <div>
          <div style={{ display: "flex", gap: 14, marginBottom: 20, flexWrap: "wrap" }}>
            <StatCard label="Recebido no mês" value={fmtCurrency(totalRecebido)} accent="#7BC142" />
            <StatCard label="Pendente no mês" value={fmtCurrency(totalPendente)} accent="#E3B455" />
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginBottom: 12 }}>
            <GhostBtn onClick={onReconcile}><Wallet size={14} /> Conciliar extrato</GhostBtn>
            <PrimaryBtn onClick={onAddFinance}><Plus size={16} /> Novo honorário</PrimaryBtn>
          </div>
          {monthFinances.length === 0 ? (
            <EmptyState icon={Wallet} title="Nenhum honorário lançado neste mês" sub="Registre os pagamentos recebidos dos clientes." />
          ) : (
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, overflow: "hidden" }}>
              <table>
                <thead><tr><th>Cliente</th><th>Tipo</th><th>Gestor responsável</th><th>Data</th><th>Valor</th><th>Status</th><th></th></tr></thead>
                <tbody>
                  {monthFinances.map((f) => {
                    const client = clients.find((c) => c.id === f.clientId);
                    const responsible = team.find((t) => t.id === f.responsibleGestorId);
                    return (
                      <tr key={f.id}>
                        <td style={{ fontWeight: 600, color: "#F2F0E6" }}>
                          <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                            {f.recurring && <Repeat size={12} color="#6B7268" />}
                            {f.serviceId && <Briefcase size={12} color="#6B7268" title="Gerado automaticamente por um Serviço" />}
                            {client?.name || "—"}
                          </div>
                        </td>
                        <td>{FINANCE_TYPE_LABELS[f.type] || "Mensalidade"}</td>
                        <td>{responsible?.name || "—"}</td>
                        <td style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 10 }}>{fmtDate(f.date)}</td>
                        <td>{fmtCurrency(f.amount)}</td>
                        <td><FinanceStatusBadge status={f.status} /></td>
                        <td>
                          <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
                            <button onClick={() => onEditFinance(f)} style={iconBtnStyle}><Pencil size={14} /></button>
                            <button onClick={() => { if (confirm("Remover este lançamento?")) onDeleteFinance(f.id); }} style={iconBtnStyle}><Trash2 size={14} /></button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {tab === "comissoes" && (
        <div>
          <div style={{ display: "flex", gap: 14, marginBottom: 20, flexWrap: "wrap", alignItems: "flex-end" }}>
            <StatCard label="Total de pró-labore no mês" value={fmtCurrency(totalComissoes)} accent="#7BC142" />
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: "16px 18px" }}>
              <div style={{ fontSize: 9.5, color: "#9BA298", fontWeight: 600, marginBottom: 8, textTransform: "uppercase", letterSpacing: ".03em" }}>Por hectare (R$/ha/ano)</div>
              <div style={{ display: "flex", gap: 8 }}>
                <input type="number" style={{ ...inputStyle, width: 100 }} value={rateInput} onChange={(e) => setRateInput(e.target.value)} />
                <GhostBtn onClick={() => onChangeRate(Number(rateInput) || 0)}>Salvar</GhostBtn>
              </div>
              <div style={{ fontSize: 9.5, color: "#6B7268", marginTop: 6 }}>= {fmtCurrency((Number(rateInput) || 0) / 12)}/ha/mês</div>
            </div>
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, padding: "16px 18px" }}>
              <div style={{ fontSize: 9.5, color: "#9BA298", fontWeight: 600, marginBottom: 8, textTransform: "uppercase", letterSpacing: ".03em" }}>De projetos (% dos honorários pagos)</div>
              <div style={{ display: "flex", gap: 8 }}>
                <input type="number" style={{ ...inputStyle, width: 100 }} value={projectRateInput} onChange={(e) => setProjectRateInput(e.target.value)} />
                <GhostBtn onClick={() => onChangeProjectRate(Number(projectRateInput) || 0)}>Salvar</GhostBtn>
              </div>
            </div>
          </div>

          {commissionRows.length === 0 ? (
            <div style={{ color: "#6B7268", fontSize: 10.5, marginBottom: 20 }}>Nenhum gestor com talhões atribuídos, honorário de projeto ou bonificação neste mês.</div>
          ) : (
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, overflow: "hidden", marginBottom: 12 }}>
              <table>
                <thead><tr><th>Gestor</th><th>Área atendida</th><th>Pró-labore (ha)</th><th>Pró-labore (projetos)</th><th>Ajuda de custo</th><th>Bonificações</th><th>Total</th><th>Pagamento</th></tr></thead>
                <tbody>
                  {commissionRows.map((r) => (
                    <tr key={r.gestor.id}>
                      <td style={{ fontWeight: 600, color: "#F2F0E6" }}>{r.gestor.name}</td>
                      <td>{r.areaHa.toLocaleString("pt-BR")} ha</td>
                      <td>{fmtCurrency(r.base)}</td>
                      <td>{fmtCurrency(r.projectShare)}</td>
                      <td>{fmtCurrency(r.ajudaCustoTotal)}</td>
                      <td>{fmtCurrency(r.bonusTotal)}</td>
                      <td style={{ fontWeight: 600, color: "#7BC142" }}>{fmtCurrency(r.total)}</td>
                      <td>
                        {proLaboreGeneratedIds.has(r.gestor.id) ? (
                          <span style={{ color: "#7BC142", fontSize: 10, fontWeight: 600 }}>✓ Gerado</span>
                        ) : (
                          <span style={{ color: "#6B7268", fontSize: 10 }}>—</span>
                        )}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 24 }}>
            <GhostBtn onClick={() => onGenerateProLaboreBills(month, commissionRows)} disabled={commissionRows.length === 0} style={commissionRows.length === 0 ? { opacity: 0.5, cursor: "not-allowed" } : {}}>
              <Receipt size={14} /> Gerar despesas de pró-labore (vence dia 10 do mês seguinte)
            </GhostBtn>
          </div>

          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 12 }}>
            <div style={{ fontSize: 10.5, fontWeight: 600, color: "#D6D3C7" }}>Bonificações do mês</div>
            <PrimaryBtn onClick={onAddBonus}><Plus size={16} /> Nova bonificação</PrimaryBtn>
          </div>
          {monthBonuses.length === 0 ? (
            <EmptyState icon={Wallet} title="Nenhuma bonificação lançada neste mês" sub="Lance bonificações avulsas por projeto elaborado." />
          ) : (
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, overflow: "hidden" }}>
              <table>
                <thead><tr><th>Gestor</th><th>Descrição</th><th>Data</th><th>Valor</th><th></th></tr></thead>
                <tbody>
                  {monthBonuses.map((b) => {
                    const gestor = team.find((t) => t.id === b.gestorId);
                    return (
                      <tr key={b.id}>
                        <td style={{ fontWeight: 600, color: "#F2F0E6" }}>{gestor?.name || "—"}</td>
                        <td>{b.description}</td>
                        <td style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 10 }}>{fmtDate(b.date)}</td>
                        <td>{fmtCurrency(b.amount)}</td>
                        <td>
                          <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
                            <button onClick={() => onEditBonus(b)} style={iconBtnStyle}><Pencil size={14} /></button>
                            <button onClick={() => { if (confirm("Remover esta bonificação?")) onDeleteBonus(b.id); }} style={iconBtnStyle}><Trash2 size={14} /></button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {tab === "despesas" && (
        <div>
          <div style={{ display: "flex", gap: 14, marginBottom: 20, flexWrap: "wrap" }}>
            <StatCard label="Pago no mês" value={fmtCurrency(totalDespesasPagas)} accent="#E38B84" />
            <StatCard label="Pendente no mês" value={fmtCurrency(totalDespesasPendentes)} accent="#E3B455" />
          </div>
          <div style={{ display: "flex", justifyContent: "flex-end", marginBottom: 12 }}>
            <PrimaryBtn onClick={onAddBill}><Plus size={16} /> Nova despesa</PrimaryBtn>
          </div>
          {monthBillsSorted.length === 0 ? (
            <EmptyState icon={Receipt} title="Nenhuma despesa lançada neste mês" sub="Registre os custos do escritório: salários, energia, manutenção, etc." />
          ) : (
            <div style={{ background: "#161D19", border: "1px solid #232B25", borderRadius: 12, overflow: "hidden" }}>
              <table>
                <thead><tr><th>Descrição</th><th>Categoria</th><th>Data</th><th>Valor</th><th>Status</th><th></th></tr></thead>
                <tbody>
                  {monthBillsSorted.map((b) => (
                    <tr key={b.id}>
                      <td style={{ fontWeight: 600, color: "#F2F0E6" }}>
                        <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
                          {b.recurring && <Repeat size={12} color="#6B7268" />}
                          {b.proLaboreMonth && <UserCog size={12} color="#6B7268" title="Gerado automaticamente pelo Pró-labore" />}
                          {b.description}
                        </div>
                      </td>
                      <td>{b.category || "—"}</td>
                      <td style={{ fontFamily: "'IBM Plex Mono', monospace", fontSize: 10 }}>{fmtDate(b.date)}</td>
                      <td>{fmtCurrency(b.amount)}</td>
                      <td><FinanceStatusBadge status={b.status} /></td>
                      <td>
                        <div style={{ display: "flex", gap: 6, justifyContent: "flex-end" }}>
                          <button onClick={() => onEditBill(b)} style={iconBtnStyle}><Pencil size={14} /></button>
                          <button onClick={() => { if (confirm("Remover esta despesa?")) onDeleteBill(b.id); }} style={iconBtnStyle}><Trash2 size={14} /></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

